import React, { useState, useEffect, useRef, useMemo, useCallback } from "react";
import { createRoot } from "react-dom/client";

/* ------------------------------------------------------------------ */
/*  Charts: hand drawn, so the app carries no charting dependency      */
/* ------------------------------------------------------------------ */

function MiniChart({ data, kind = "line", height = 168, color = "#057BC1" }) {
  const pts = data.filter((d) => d.value != null && !isNaN(d.value));
  if (pts.length < (kind === "bar" ? 1 : 2)) return null;
  const vals = pts.map((d) => d.value);
  const max = Math.max(...vals);
  const min = Math.min(...vals);
  const pad = (max - min) * 0.18 || Math.max(max * 0.1, 1);
  const lo = kind === "bar" ? 0 : Math.max(0, min - pad);
  const hi = max + pad;
  const W = 620, H = height, L = 38, R = 8, T = 10, B = 24;
  const iw = W - L - R, ih = H - T - B;
  const n = data.length;
  const px = (i) => (n === 1 ? L + iw / 2 : L + (i / (n - 1)) * iw);
  const bx = (i) => L + (i + 0.5) * (iw / n);
  const py = (v) => T + ih - ((v - lo) / (hi - lo || 1)) * ih;
  const ticks = [lo, (lo + hi) / 2, hi];

  let path = "";
  let pen = false;
  data.forEach((d, i) => {
    if (d.value == null || isNaN(d.value)) { pen = false; return; }
    path += (pen ? " L " : " M ") + px(i).toFixed(1) + " " + py(d.value).toFixed(1);
    pen = true;
  });

  const labelAt = [0, Math.floor((n - 1) / 2), n - 1].filter((v, i, a) => a.indexOf(v) === i);

  return (
    <svg viewBox={`0 0 ${W} ${H}`} width="100%" height={H} className="chart" role="img">
      {ticks.map((t, i) => (
        <g key={i}>
          <line x1={L} x2={W - R} y1={py(t)} y2={py(t)} stroke="var(--hair-2)" strokeWidth="1" />
          <text x={L - 7} y={py(t) + 3.5} textAnchor="end" className="ct">{Math.round(t)}</text>
        </g>
      ))}
      {kind === "bar"
        ? data.map((d, i) =>
            d.value == null ? null : (
              <rect key={i} x={bx(i) - Math.min(16, iw / n / 2.4)} y={py(d.value)}
                width={Math.min(32, iw / n / 1.2)} height={Math.max(2, T + ih - py(d.value))}
                rx="3" fill={color} />
            )
          )
        : (
          <>
            <path d={path} fill="none" stroke={color} strokeWidth="2.2" strokeLinejoin="round" strokeLinecap="round" />
            {data.map((d, i) =>
              d.value == null ? null : <circle key={i} cx={px(i)} cy={py(d.value)} r="2.8" fill={color} />
            )}
          </>
        )}
      {labelAt.map((i) => (
        <text key={i} x={kind === "bar" ? bx(i) : px(i)} y={H - 6}
          textAnchor={i === 0 ? "start" : i === n - 1 ? "end" : "middle"} className="ct">
          {data[i] && data[i].label}
        </text>
      ))}
    </svg>
  );
}

