// A tap for the longer version. The screen says what to do; this says why, for the
// people who want it, without putting a paragraph in front of everyone else.
function Info({ title, children, label }) {
  const [open, setOpen] = useState(false);
  return (
    <>
      <button
        className={label ? "btn" : "infob"}
        aria-label={label ? undefined : "More about " + title}
        // some of these sit inside a <summary>, where a plain click would roll the
        // section up underneath the sheet it just opened
        onClick={(e) => {
          e.preventDefault();
          e.stopPropagation();
          setOpen(true);
        }}
      >
        {label || "i"}
      </button>
      {open && (
        <>
          <div className="scrim" onClick={() => setOpen(false)} />
          <div className="modal" role="dialog" aria-modal="true">
            <div className="modal-head">
              <div>
                <span className="wordmark">Clear</span>
                <h3>{title}</h3>
              </div>
              <button className="modal-x" aria-label="Close" onClick={() => setOpen(false)}>
                {"×"}
              </button>
            </div>
            <div className="about">{children}</div>
          </div>
        </>
      )}
    </>
  );
}

// First run, and reachable afterwards from an empty care card. Builds the plan by
// tapping suggestions rather than starting from a blank form, but nothing is chosen
// until it is chosen: the suggestions are categories, not a regimen.
function Setup({ regimen, track, conditions, unit, onChange, onTrack, onConditions, onUnit, onClose }) {
  const [step, setStep] = useState(1);
  const [rows, setRows] = useState(() => JSON.parse(JSON.stringify(regimen || [])));
  const [own, setOwn] = useState("");
  const has = (n) => rows.some((r) => r.name.toLowerCase() === n.toLowerCase());
  const add = (name, target) =>
    setRows((d) => [...d, { id: "r" + Date.now() + d.length, name, target, note: "", active: true }]);
  const drop = (id) => setRows((d) => d.filter((r) => r.id !== id));
  const setTarget = (id, target) => setRows((d) => d.map((r) => (r.id === id ? { ...r, target } : r)));

  return (
    <>
      <div className="scrim" onClick={onClose} />
      <div className="modal" role="dialog" aria-modal="true">
        <div className="modal-head">
          <div>
            <span className="wordmark">{"Clear · " + step + " of 3"}</span>
            <h3>
              {step === 1 ? "What do you live with?" : step === 2 ? "Your daily care" : "What can you measure?"}
            </h3>
          </div>
          <button className="modal-x" aria-label="Close" onClick={onClose}>
            {"×"}
          </button>
        </div>

        {step === 1 ? (
        <>
        <ConditionPicker conditions={conditions || []} onChange={onConditions} bare />
        <button className="btn pri wide" style={{ marginTop: 18 }} onClick={() => setStep(2)}>
          Next
        </button>
        </>
        ) : step === 2 ? (
        <>
        <div className="about">
          <p>
            What do you do on an ordinary day to keep on top of things? Add each one and how many
            times a day you do it. The ring on your log counts them off.
          </p>
        </div>

        {rows.length > 0 && (
          <>
            <div className="rowlab">Your plan</div>
            {rows.map((r) => (
              <div className="planrow" key={r.id}>
                <input
                  className="inp"
                  value={r.name}
                  placeholder="Name"
                  onChange={(e) => setRows((d) => d.map((x) => (x.id === r.id ? { ...x, name: e.target.value } : x)))}
                />
                <div className="planfoot">
                  <span className="note">Times a day</span>
                  <div className="chips">
                    {[1, 2, 3, 4].map((n) => (
                      <button
                        key={n}
                        className={"chip" + (r.target === n ? " on" : "")}
                        onClick={() => setTarget(r.id, n)}
                      >
                        {n}
                      </button>
                    ))}
                    <button className="chip add" onClick={() => drop(r.id)}>
                      Remove
                    </button>
                  </div>
                </div>
              </div>
            ))}
          </>
        )}

        <div className="rowlab">Common ones</div>
        <div className="chips">
          {SUGGESTED_CARE.filter((sug) => !has(sug.name)).map((sug) => (
            <button key={sug.name} className="chip add" onClick={() => add(sug.name, sug.target)}>
              {"+ " + sug.name}
            </button>
          ))}
        </div>
        <div className="note" style={{ marginTop: 10 }}>
          A list to save you typing, not a recommendation. Your team decides what belongs here.
        </div>

        <div className="rowlab">Something else</div>
        <div className="chipwrap">
          <input
            className="inp"
            placeholder="Name it"
            value={own}
            onChange={(e) => setOwn(e.target.value)}
            onKeyDown={(e) => {
              if (e.key === "Enter" && own.trim()) {
                add(own.trim(), 1);
                setOwn("");
              }
            }}
          />
          <button
            className="btn pri"
            onClick={() => {
              if (own.trim()) add(own.trim(), 1);
              setOwn("");
            }}
          >
            Add
          </button>
        </div>

        <button
          className="btn pri wide"
          style={{ marginTop: 18 }}
          onClick={() => {
            onChange(rows.filter((r) => r.name.trim()));
            setStep(3);
          }}
        >
          {rows.length ? "Save my plan" : "Skip for now"}
        </button>
        <div className="note" style={{ marginTop: 10 }}>
          You can change any of this later from Edit plan.
        </div>
        </>
        ) : (
        <>
        {/* Asked once, here, so nobody meets four boxes for devices they do not own. */}
        <div className="about">
          <p>
            Leave on whatever you can actually measure. Anything you switch off will not be asked
            for, and will not appear on your daily page.
          </p>
        </div>
        <TrackSettings track={track || {}} onChange={onTrack} unit={unit} onUnit={onUnit} bare />
        <button className="btn pri wide" style={{ marginTop: 18 }} onClick={onClose}>
          Start logging
        </button>
        <div className="note" style={{ marginTop: 10 }}>
          All of this lives under Report → Settings if you want to change it later.
        </div>
        </>
        )}
      </div>
    </>
  );
}

function Reminders({ times, onChange, onAdd }) {
  const set = (i, v) => onChange(times.map((t, k) => (k === i ? v : t)));
  return (
    <div className="card">
      <div className="card-t">
        <span>Daily reminders</span>
      </div>
      <div className="note" style={{ marginBottom: 12 }}>
        Set the times you mean to do your care, and put them in your phone's calendar. It
        will remind you whether or not the app is open.
      </div>
      {times.map((t, i) => (
        <div className="chipwrap" key={i} style={{ marginTop: i ? 8 : 0 }}>
          <input className="inp" type="time" value={t} onChange={(e) => set(i, e.target.value)} />
          <button className="btn" onClick={() => onChange(times.filter((_, k) => k !== i))}>
            Remove
          </button>
        </div>
      ))}
      <div className="chips" style={{ marginTop: times.length ? 12 : 0 }}>
        <button className="chip add" onClick={() => onChange([...times, times.length ? "20:00" : "08:00"])}>
          {times.length ? "+ Another time" : "+ Add a time"}
        </button>
      </div>
      {times.length > 0 && (
        <button className="btn pri wide" style={{ marginTop: 14 }} onClick={onAdd}>
          Add {times.length === 1 ? "this" : "these"} to my calendar
        </button>
      )}
      <Info title="Why the calendar" label="Why not a notification?">
        <p>
          A notification that arrives while the app is shut has to be sent from somewhere. That
          means a server holding a subscription for every person using this, which is the one
          thing this app has never done and is not going to start doing for a reminder.
        </p>
        <p>
          A calendar entry does the same job without any of that. It fires at the right time,
          it works with the app closed and with no signal, and it is yours — you can move it,
          silence it or delete it in your own calendar, without asking us.
        </p>
        <p>
          It repeats daily from today. Adding it again later replaces nothing, so delete the old
          entry in your calendar if you change the time.
        </p>
      </Info>
    </div>
  );
}

function ConditionPicker({ conditions, onChange, bare }) {
  const list = conditions || [];
  const on = (k) => list.indexOf(k) !== -1;
  const toggle = (k) => onChange(on(k) ? list.filter((x) => x !== k) : [...list, k]);
  const Wrap = "div";
  return (
    <Wrap className={bare ? "" : "card"}>
      {!bare && (
        <div className="card-t">
          <span>What you live with</span>
        </div>
      )}
      <div className="note" style={{ marginBottom: 12 }}>
        Pick any that apply. They often come together, and each one counts an exacerbation
        differently, so the app scores each rule separately rather than blending them.
      </div>
      {CONDITIONS.map((c) => (
        <button
          key={c.key}
          className={"trackrow" + (on(c.key) ? " on" : "")}
          aria-pressed={on(c.key)}
          onClick={() => toggle(c.key)}
        >
          <span className="tr-tx">
            <b>{c.label}</b>
          </span>
          <span className="tr-sw" aria-hidden="true">
            <i />
          </span>
        </button>
      ))}
      {!list.length && (
        <div className="note" style={{ marginTop: 10 }}>
          Nothing picked, so the bronchiectasis features are counted by default.
        </div>
      )}
    </Wrap>
  );
}

function TrackSettings({ track, onChange, bare, unit, onUnit }) {
  const on = (k) => track[k] === true;
  const Wrap = bare ? "div" : "div";
  return (
    <Wrap className={bare ? "" : "card"}>
      {!bare && (
        <div className="card-t">
          <span>What you track</span>
        </div>
      )}
      <div className="note" style={{ marginBottom: 12 }}>
        Turn off anything you do not measure. It hides the field and stops the reminders.
        Nothing you have already recorded is removed.
      </div>
      {TRACKABLE.map((t) => (
        <React.Fragment key={t.key}>
        <button
          className={"trackrow" + (on(t.key) ? " on" : "")}
          aria-pressed={on(t.key)}
          onClick={() => onChange({ ...track, [t.key]: !on(t.key) })}
        >
          <span className="tr-tx">
            <b>{t.label}</b>
            <small>{t.note}</small>
          </span>
          <span className="tr-sw" aria-hidden="true">
            <i />
          </span>
        </button>
        {t.key === "weight" && on("weight") && onUnit && (
          <div className="chips" style={{ margin: "2px 0 10px" }}>
            {["kg", "lb"].map((u) => (
              <button
                key={u}
                className={"chip" + ((unit || "kg") === u ? " on" : "")}
                onClick={() => onUnit(u)}
              >
                {u}
              </button>
            ))}
          </div>
        )}
        </React.Fragment>
      ))}
    </Wrap>
  );
}

function Seg({ options, value, onChange, small, alarm }) {
  return (
    <div className={"seg" + (small ? " sm" : "") + (alarm ? " alarm" : "")}>
      {options.map((o) => (
        <button
          key={o.v}
          className={value === o.v ? "on" : ""}
          onClick={() => onChange(value === o.v ? null : o.v)}
        >
          {o.label.split("\n").map((l, i) => (
            <span key={i} style={{ display: "block" }}>{l}</span>
          ))}
        </button>
      ))}
    </div>
  );
}

function AirQuality({ day, date, locations, onSet, onAddLocation }) {
  const [busy, setBusy] = useState(false);
  const [err, setErr] = useState("");
  const [picking, setPicking] = useState(false);
  const [manual, setManual] = useState(false);
  const [q, setQ] = useState("");
  const [hits, setHits] = useState([]);
  const aqi = day.aqi;
  const loc = (aqi && aqi.location) || (locations[0] && locations[0].name) || "";
  const current = locations.find((l) => l.name === loc) || locations[0];

  const [step, setStep] = useState("");

  const pull = async (useLoc) => {
    const L = useLoc || current;
    if (!L) {
      setErr("No location set. Open Location and search for one.");
      return;
    }
    setBusy(true);
    setErr("");
    try {
      const r = await getAqi(L, date, setStep);
      onSet({ ...r, location: L.name, at: new Date().toISOString() });
      setStep("");
    } catch (e) {
      setErr(e && e.message ? e.message : "Both sources failed.");
      setStep("");
    }
    setBusy(false);
  };

  const search = async () => {
    if (!q.trim()) return;
    setBusy(true);
    setErr("");
    try {
      setHits(await geocode(q.trim()));
    } catch (e) {
      setErr("Place lookup is unavailable here.");
    }
    setBusy(false);
  };

  const band = aqi && aqi.value != null ? aqiBand(aqi.value) : null;

  return (
    <div className="card">
      <div className="card-t">
        <span>Air quality</span>
        <button className="btn sm" onClick={() => setPicking((v) => !v)}>
          {picking ? "Close" : "Location"}
        </button>
      </div>

      <div className="aq">
        {band ? (
          <div className="aq-dial">
            <svg viewBox="0 0 70 70" width="70" height="70">
              <circle cx="35" cy="35" r="30" fill="none" stroke="var(--paper-2)" strokeWidth="5" />
              <g transform="rotate(-90 35 35)">
                <circle
                  cx="35" cy="35" r="30" fill="none" stroke={band.hex} strokeWidth="5" strokeLinecap="round"
                  strokeDasharray={2 * Math.PI * 30}
                  strokeDashoffset={2 * Math.PI * 30 * (1 - Math.min(aqi.value / 300, 1))}
                />
              </g>
            </svg>
            <span className="aq-num">
              <b>{aqi.value}</b>
              <span>AQI</span>
            </span>
          </div>
        ) : (
          <div className="aq-empty" />
        )}
        <div className="aq-body">
          <div className="lab">{band ? band.label : busy ? step || "Checking" : "Not recorded"}</div>
          <div className="sub">
            {loc || "No location set"}
            {aqi && aqi.pm25 != null ? ` · PM2.5 ${aqi.pm25}` : ""}
            {aqi && aqi.source ? ` · ${aqi.source}` : ""}
          </div>
        </div>
        <button className="btn sm" disabled={busy} onClick={() => pull()}>
          {busy ? "…" : aqi ? "Refresh" : "Fetch"}
        </button>
      </div>

      {err && (
        <div className="banner" style={{ marginTop: 12 }}>
          {err}
          <div style={{ marginTop: 10 }}>
            <a
              className="btn sm"
              href="https://www.iqair.com/thailand/bangkok"
              target="_blank"
              rel="noopener noreferrer"
              style={{ display: "inline-block", textDecoration: "none" }}
            >
              Open IQAir
            </a>
          </div>
        </div>
      )}

      {picking && (
        <>
          <div className="chips" style={{ marginTop: 12 }}>
            {locations.map((l) => (
              <button
                key={l.name}
                className={"chip" + (l.name === loc ? " on" : "")}
                onClick={() => pull(l)}
              >
                {l.name}
              </button>
            ))}
          </div>
          <div className="locrow">
            <input
              className="inp"
              placeholder="Search a city or district"
              value={q}
              onChange={(e) => setQ(e.target.value)}
              onKeyDown={(e) => e.key === "Enter" && search()}
            />
            <button className="btn pri" onClick={search}>Find</button>
          </div>
          {hits.length > 0 && (
            <div className="loclist">
              {hits.map((h) => (
                <button
                  key={h.name + h.lat}
                  className="locopt"
                  onClick={() => {
                    onAddLocation(h);
                    setHits([]);
                    setQ("");
                    setPicking(false);
                    pull(h);
                  }}
                >
                  {h.name}
                </button>
              ))}
            </div>
          )}
        </>
      )}

      {!busy && (
        <div className="locrow">
          <input
            className="inp"
            type="number"
            inputMode="numeric"
            placeholder={aqi ? "Override the AQI by hand" : "Or type today's AQI"}
            onKeyDown={(e) => {
              if (e.key === "Enter" && e.target.value) {
                onSet({ value: Number(e.target.value), pm25: null, source: "Entered by hand", location: loc });
                e.target.value = "";
                setManual(false);
              }
            }}
          />
        </div>
      )}
    </div>
  );
}

function PeakFlowInsight({ days, date, value }) {
  const v = parseFloat(value);
  if (isNaN(v)) return null;
  const c = peakFlowContext(days, v, date);

  if (c.needed) {
    return (
      <div className="insight">
        <b>{v}</b> L/min recorded. {c.needed} more reading{c.needed === 1 ? "" : "s"} on well days and this can
        start telling you what a given number means for you, since peak flow is read against your own best rather
        than against anyone else's.
      </div>
    );
  }

  const cls = c.zone === "green" ? "good" : c.zone === "amber" ? "warn" : "bad";
  const text =
    c.zone === "green"
      ? "That sits in what an action plan calls the green zone, 80 to 100 percent of your own best. Nothing to act on."
      : c.zone === "amber"
      ? "That is the amber zone, 50 to 80 percent of your best. On most written action plans this is the range where you step treatment up and let your team know, particularly if it stays there for a couple of days."
      : "That is below 50 percent of your best, the red zone. On a standard action plan that means contacting your team the same day, and urgent care if breathing is difficult.";

  return (
    <div className={"insight " + cls}>
      <b>
        {v} L/min · {c.pct}% of your best
      </b>
      <div className="zonebar">
        <i className="z-red" />
        <i className="z-amb" />
        <i className="z-grn" />
      </div>
      <div className="zonemark">
        <span style={{ left: Math.min(Math.max(c.pct, 2), 100) + "%" }} />
      </div>
      <div style={{ marginTop: 12 }}>
        {text} Your best of {c.best} is the highest of {c.n} readings taken on well days in the last year. If your
        team has written you a personal best, use theirs.
      </div>
    </div>
  );
}

function OtherInsights({ day, days, date }) {
  const out = [];
  const t = parseFloat(day.temp);
  if (!isNaN(t)) {
    if (t >= 38)
      out.push(["warn", `${t}°C is a fever. Alongside a colour change in your sputum it is one of the features that counts toward an exacerbation.`]);
    else if (t >= 37.5)
      out.push(["", `${t}°C is slightly raised rather than a fever, which is usually taken as 38 and above.`]);
  }
  const o = parseFloat(day.spo2);
  if (!isNaN(o)) {
    if (o >= 95) out.push(["good", `${o}% is a normal home reading.`]);
    else if (o >= 93)
      out.push(["", `${o}% is a little below the usual 95 to 100. Home meters are easily thrown off by cold hands, nail polish or movement, so take it again before reading anything into it.`]);
    else if (o >= 90)
      out.push(["warn", `${o}% is low enough to be worth a call to your team today rather than watching it.`]);
    else out.push(["bad", `${o}% is low. Take it again on a warm still hand, and if it holds, seek help now rather than later.`]);
  }
  const hr = parseFloat(day.restHr);
  if (!isNaN(hr)) {
    const base = Object.keys(days)
      .filter((k) => k !== date && days[k].status === "well" && days[k].restHr !== "")
      .map((k) => parseFloat(days[k].restHr))
      .filter((x) => !isNaN(x));
    if (base.length >= 5) {
      const m = median(base);
      const up = Math.round(((hr - m) / m) * 100);
      if (up >= 12)
        out.push(["warn", `Resting heart rate is ${up}% above your usual ${m}. A rise often shows up a day or two before symptoms do.`]);
      else out.push(["", `Resting heart rate is close to your usual ${m}.`]);
    }
  }
  if (!out.length) return null;
  return (
    <>
      {out.map(([cls, text], i) => (
        <div className={"insight " + cls} key={i}>
          {text}
        </div>
      ))}
    </>
  );
}

function EpisodeHandover({ episodes, days, regimen }) {
  const [open, setOpen] = useState(false);
  const [detail, setDetail] = useState(false);
  const [msg, setMsg] = useState("");
  const ep = episodes.length ? episodes[episodes.length - 1] : null;
  if (!ep) return null;

  const summary = episodeSummary(ep, days, regimen);
  const full = detail ? summary + "\n\n" + episodeText(ep, days) : summary;

  if (!open) {
    return (
      <button className="btn wide" style={{ marginTop: 16 }} onClick={() => setOpen(true)}>
        Write this up for my doctor
      </button>
    );
  }

  return (
    <div className="card">
      <div className="card-t">
        <span>For your team</span>
        <button className="btn sm" onClick={() => setOpen(false)}>Close</button>
      </div>
      <div className="handover">{full}</div>
      <div className="btnrow" style={{ marginTop: 12 }}>
        <button
          className="btn pri"
          onClick={async () => {
            const ok = await copyText(full);
            setMsg(ok ? "Copied" : "Copy failed, select the text instead");
            setTimeout(() => setMsg(""), 1800);
          }}
        >
          Copy
        </button>
        <button className="btn" onClick={() => setDetail((v) => !v)}>
          {detail ? "Just the summary" : "Add day by day"}
        </button>
      </div>
      {msg && <div className="note" style={{ marginTop: 9 }}>{msg}</div>}
      <div className="note" style={{ marginTop: 10 }}>
        Every figure comes from an entry you made.
      </div>
    </div>
  );
}

// Doubles as the first-run welcome and, after that, the settings sheet. The two
// share a shell because the things worth saying on day one \u2014 it lives on this
// phone, nobody else has a copy, back it up \u2014 are the things worth being able to
// find again, and a second sheet holding only those would be a sheet nobody opens.
function About({
  onClose,
  intro,
  onAck,
  onShareBackup,
  onShareWeek,
  settings,
}) {
  const close = intro ? onAck : onClose;
  return (
    <>
      <div className="scrim" onClick={close} />
      <div className="modal" role="dialog" aria-modal="true">
        <div className="modal-head">
          <div>
            <span className="wordmark">Clear</span>
            <h3>{intro ? "Welcome" : "Settings"}</h3>
          </div>
          <button className="modal-x" onClick={close} aria-label="Close">
            {"\u00d7"}
          </button>
        </div>

        {!intro && settings && (
          <div className="setgrp">
            <ConditionPicker conditions={settings.conditions || []} onChange={settings.onConditions} />
            <Reminders
              times={settings.remindTimes || []}
              onChange={settings.onRemind}
              onAdd={settings.onAddRemind}
            />
            <TrackSettings
              track={settings.track || {}}
              onChange={settings.onTrack}
              unit={settings.unit}
              onUnit={settings.onUnit}
            />
          </div>
        )}

        {!intro && <div className="sectionhead">How it works</div>}

        <div className="pts">
          <div className="pt">
            <span className="n">1</span>
            <span className="tx">
              <b>Everything stays on this phone</b>
              No account, no server. Nothing you type is sent anywhere.
            </span>
          </div>
          <div className="pt">
            <span className="n">2</span>
            <span className="tx">
              <b>Nobody else has a copy</b>
              Clearing your browser data erases it, and it cannot be recovered.
            </span>
          </div>
          <div className="pt">
            <span className="n">3</span>
            <span className="tx">
              <b>Back it up once a month</b>
              One small file. Save it to Files, or email it to yourself.
            </span>
          </div>
        </div>

        <div className="btnrow" style={{ marginTop: 18 }}>
          <button className="btn pri" onClick={onShareBackup}>
            Back up now
          </button>
          <button className="btn" onClick={close}>
            {intro ? "Start logging" : "Close"}
          </button>
        </div>

        <details className="more">
          <summary>More about backups and losing data</summary>
          <p className="fine">
            Your log is also erased by private browsing, and on some devices by deleting the app from your home
            screen. Browsers clear data for sites left unopened for a long stretch, which is why adding this to your
            home screen matters. None of it is recoverable.
          </p>
          <p className="fine">
            To restore, open Report and tap <strong>Restore backup</strong>. Worth trying the whole round trip once
            now, while you have nothing to lose. <strong>Check a backup file</strong> will read a file and confirm
            what is in it without changing anything.
          </p>
          <p className="fine">
            The app also keeps automatic copies of the last few days, under Report. Those live in the same browser
            storage, so they vanish with everything else. They are not a backup.
          </p>
        </details>

        <details className="more">
          <summary>Getting around, and what this is not</summary>
          <p className="fine">
            Swipe left and right to change day. Tap Month for the calendar, or any column in the sputum ribbon to
            jump back to that day.
          </p>
          <p className="fine">
            You can also copy the last seven days out as readable text to paste into a message. That is for reading,
            not restoring.
          </p>
          <div className="btnrow" style={{ marginTop: 4 }}>
            <button className="btn sm" onClick={onShareWeek}>
              Copy this week as text
            </button>
          </div>
          <p className="fine">
            Clear is a diary that does arithmetic. It does not diagnose anything, and thresholds it mentions are
            general reference points rather than a plan written for you. If you are unwell, speak to your team.
          </p>
          <p className="fine">Clear {BUILD}</p>
        </details>
      </div>
    </>
  );
}

// Eight teeth, drawn rather than typed: an emoji gear renders differently on
// every platform and a font icon would mean carrying a second font.
function Gear() {
  const teeth = Array.from({ length: 8 }, (_, i) => i * 45);
  return (
    <svg viewBox="0 0 24 24" width="18" height="18" aria-hidden="true" focusable="false">
      {/* stubby teeth that sit into the body, and a hollow centre — long spokes
          and a filled hub read as a sun rather than a gear */}
      <g fill="currentColor">
        {teeth.map((a) => (
          <rect key={a} x="10.4" y="2" width="3.2" height="4.2" rx="1.1" transform={`rotate(${a} 12 12)`} />
        ))}
      </g>
      <circle cx="12" cy="12" r="5.9" fill="none" stroke="currentColor" strokeWidth="3.3" />
    </svg>
  );
}

// Dismissable, but it cannot be silenced for good. What gets remembered is which
// signals were showing and how serious each one was — so a new signal, or an
// existing one stepping up from a note to a watch, brings the card straight back.
// Only the exact set you actually read stays hidden.
// A coloured callout with a close on it. What is remembered is not "this was
// closed" but the state it was in when you closed it — so the same wording on
// the same day stays gone, while a worse count, a deeper shift, or simply
// tomorrow brings it back. Closing one of these is acknowledging what it says,
// not switching it off.
function Callout({ id, sig, noted, onNote, cls, children }) {
  if ((noted || {})[id] === sig) return null;
  return (
    <div className={cls + " hasx"}>
      {children}
      <button className="calloutx" onClick={() => onNote(id, sig)} aria-label="Dismiss">
        {"×"}
      </button>
    </div>
  );
}

// A card heading you can roll up. The open state is remembered per section, so
// somebody who never fills symptoms in is not reopening the same list every day.
// Until it has been touched the fallback decides, and every fallback errs open
// when the day already holds something — collapsing must never hide an entry.
function Fold({ id, title, hint, info, open, onToggle, children }) {
  return (
    <details
      open={open}
      onToggle={(e) => {
        const v = e.currentTarget.open;
        if (v !== open) onToggle(id, v);
      }}
    >
      <summary className="card-t foldy">
        <span className="ttl">
          {title}
          {info}
        </span>
        <span className="hint">
          {hint}
          <i className="chev" aria-hidden="true" />
        </span>
      </summary>
      {children}
    </details>
  );
}

function EarlyWarning({ days, regimen, seen, onDismiss }) {
  const signals = useMemo(() => earlyWarning(days, regimen), [days, regimen]);
  // built from the kind and level, never the wording: the sentences carry live
  // numbers, and keying on those would resurface the card on every decimal
  const sig = signals.map((x) => x.level + ":" + x.key).sort().join("|");
  if (!signals.length || seen === sig) return null;
  const watch = signals.some((x) => x.level === "watch");
  return (
    <div className="card">
      <div className="card-t">
        <span>{watch ? "Worth watching" : "Drifting"}</span>
        <button className="cardx" onClick={() => onDismiss(sig)} aria-label="Dismiss">
          {"×"}
        </button>
      </div>
      {signals.map((x, i) => (
        <div className={"insight " + (x.level === "watch" ? "warn" : "")} key={i} style={i ? {} : { marginTop: 0 }}>
          {x.text}
        </div>
      ))}
      <div className="note" style={{ marginTop: 11 }}>
        Read from your own history, not from anyone else's numbers. A single reading is noise; these only appear
        when a run of them moves together. Close it once you have read it — it comes back if something new shows
        up, or if any of this gets worse.
      </div>
    </div>
  );
}

function RescuePack({ pack, onChange, onStartCourse }) {
  const [edit, setEdit] = useState(false);
  const [draft, setDraft] = useState(() => JSON.parse(JSON.stringify(pack)));
  const today = todayISO();

  const status = (item) => {
    if (!item.expiry) return { cls: "", text: "no expiry recorded" };
    const left = diffDays(today, item.expiry);
    if (left < 0) return { cls: "bad", text: `expired ${Math.abs(left)} days ago` };
    if (left <= 60) return { cls: "warn", text: `expires in ${left} days` };
    return { cls: "good", text: `good until ${fmtShortYr(item.expiry)}` };
  };

  if (edit) {
    const set = (i, patch) => setDraft((d) => d.map((r, k) => (k === i ? { ...r, ...patch } : r)));
    return (
      <div className="card">
        <div className="card-t"><span>Rescue pack</span></div>
        {draft.map((r, i) => (
          <div className="planrow" key={r.id}>
            <input className="inp" placeholder="Medication" value={r.name} onChange={(e) => set(i, { name: e.target.value })} />
            <input className="inp" placeholder="Dose and course length" value={r.dose} onChange={(e) => set(i, { dose: e.target.value })} />
            <div className="planfoot">
              <span className="note">Expiry</span>
              <input className="inp" type="date" style={{ maxWidth: 170 }} value={r.expiry || ""} onChange={(e) => set(i, { expiry: e.target.value })} />
              <button className="btn sm" onClick={() => setDraft((d) => d.filter((_, k) => k !== i))}>Remove</button>
            </div>
          </div>
        ))}
        <div className="btnrow" style={{ marginTop: 12 }}>
          <button className="btn" onClick={() => setDraft((d) => [...d, { id: "p" + Date.now(), name: "", dose: "", expiry: "" }])}>
            Add a medication
          </button>
          <button className="btn pri" onClick={() => { onChange(draft.filter((r) => r.name.trim())); setEdit(false); }}>
            Save
          </button>
          <button className="btn" onClick={() => { setDraft(JSON.parse(JSON.stringify(pack))); setEdit(false); }}>Cancel</button>
        </div>
      </div>
    );
  }

  return (
    <div className="card">
      <div className="card-t">
        <span>Rescue pack</span>
        <button className="btn sm" onClick={() => { setDraft(JSON.parse(JSON.stringify(pack))); setEdit(true); }}>
          {pack.length ? "Edit" : "Add"}
        </button>
      </div>
      {pack.length === 0 ? (
        <div className="note">
          Standby antibiotics you keep at home, with their expiry dates.
        </div>
      ) : (
        pack.map((r) => {
          const st = status(r);
          return (
            <div key={r.id} style={{ paddingTop: 4 }}>
              <div className="course">
                <div className="nm">
                  {r.name}
                  <small>{r.dose || "dose not recorded"}</small>
                </div>
                {onStartCourse && (
                  <button className="btn sm" onClick={() => onStartCourse(r)}>Start</button>
                )}
              </div>
              <div className={"insight " + st.cls} style={{ marginTop: 0 }}>
                {st.text}
                {r.lastUsed ? ` · last used ${fmtShortYr(r.lastUsed)}` : ""}
              </div>
            </div>
          );
        })
      )}
    </div>
  );
}

function Appointment({ appt, questions, onAppt, onQuestions }) {
  const [text, setText] = useState("");
  const add = () => {
    const v = text.trim();
    if (!v) return;
    onQuestions([...questions, { id: "q" + Date.now(), text: v, done: false }]);
    setText("");
  };
  const toggle = (id) => onQuestions(questions.map((q) => (q.id === id ? { ...q, done: !q.done } : q)));
  const drop = (id) => onQuestions(questions.filter((q) => q.id !== id));
  const open = questions.filter((q) => !q.done);

  return (
    <div className="card">
      <div className="card-t">
        <span>Next appointment</span>
        {appt.date && <span className="hint">{diffDays(todayISO(), appt.date)} days away</span>}
      </div>
      <div className="locrow" style={{ marginTop: 0 }}>
        <input className="inp" type="date" value={appt.date || ""} onChange={(e) => onAppt({ ...appt, date: e.target.value })} />
        <input className="inp" placeholder="Who with" value={appt.who || ""} onChange={(e) => onAppt({ ...appt, who: e.target.value })} />
      </div>

      <div className="rowlab">To raise</div>
      {questions.length === 0 && <div className="note">Nothing on the list yet.</div>}
      {questions.map((q) => (
        <div className="sym" key={q.id}>
          <button
            className={"tog" + (q.done ? " on" : "")}
            style={{ flex: 1, background: "none", padding: "4px 0" }}
            onClick={() => toggle(q.id)}
          >
            <span className="box">{q.done ? "\u2713" : ""}</span>
            <span style={{ textDecoration: q.done ? "line-through" : "none", opacity: q.done ? 0.55 : 1 }}>
              {q.text}
            </span>
          </button>
          <button className="btn sm" onClick={() => drop(q.id)}>{"\u00d7"}</button>
        </div>
      ))}
      <div className="chipwrap">
        <input
          className="inp"
          placeholder="Add something to ask"
          value={text}
          onChange={(e) => setText(e.target.value)}
          onKeyDown={(e) => e.key === "Enter" && add()}
        />
        <button className="btn pri" onClick={add}>Add</button>
      </div>
      {open.length > 0 && (
        <div className="note" style={{ marginTop: 10 }}>
          {open.length} thing{open.length === 1 ? "" : "s"} to raise. These print with your report.
        </div>
      )}
    </div>
  );
}

function PeakFlowReminder({ lastPF, date, onSave, onDismiss }) {
  const [v, setV] = useState("");
  const save = () => {
    if (!v) return;
    onSave(v);
    setV("");
  };
  return (
    <div className="remind">
      <span className="txt">
        Weekly peak flow
        <small>
          {lastPF ? `last reading ${diffDays(lastPF, date)} days ago` : "no reading yet"} · best of three
        </small>
      </span>
      <input
        type="number"
        inputMode="numeric"
        placeholder="L/min"
        value={v}
        onChange={(e) => setV(e.target.value)}
        onKeyDown={(e) => e.key === "Enter" && save()}
        aria-label="Peak flow reading"
      />
      <button className="ok" disabled={!v} onClick={save} aria-label="Save peak flow">
        {"\u2713"}
      </button>
      <button className="x" onClick={onDismiss} aria-label="Not now">
        {"\u00d7"}
      </button>
    </div>
  );
}

function PlanEditor({ regimen, onChange, onClose }) {
  const [draft, setDraft] = useState(() => JSON.parse(JSON.stringify(regimen)));
  const set = (i, patch) => setDraft((d) => d.map((r, k) => (k === i ? { ...r, ...patch } : r)));
  const add = () =>
    setDraft((d) => [...d, { id: "r" + Date.now(), name: "", target: 1, note: "", active: true }]);
  return (
    <div className="card flat">
      <div className="note" style={{ marginBottom: 12 }}>
        Set what a full day looks like for you.
        <Info title="Your care plan">
          <p>Doses a day is what the ring counts up to.</p>
          <p>
            Archiving a treatment takes it off today's list but keeps it in your history, so past days still show
            what you were actually doing at the time.
          </p>
          <p>Changing the plan only affects days from here on.</p>
        </Info>
      </div>
      {draft.map((r, i) => (
        <div key={r.id} className="planrow">
          <input
            className="inp"
            placeholder="Treatment name"
            value={r.name}
            onChange={(e) => set(i, { name: e.target.value })}
          />
          <input
            className="inp"
            placeholder="Dose, optional"
            value={r.note}
            onChange={(e) => set(i, { note: e.target.value })}
          />
          <div className="planfoot">
            <span className="note">Doses a day</span>
            <div className="seg sm" style={{ maxWidth: 190 }}>
              {[0, 1, 2, 3, 4].map((n) => (
                <button key={n} className={r.target === n ? "on" : ""} onClick={() => set(i, { target: n })}>
                  {n}
                </button>
              ))}
            </div>
            <button className="btn sm" onClick={() => set(i, { active: !r.active })}>
              {r.active ? "Pause" : "Resume"}
            </button>
          </div>
          {!r.active && <div className="note" style={{ marginTop: 6 }}>Paused</div>}
        </div>
      ))}
      <div className="btnrow" style={{ marginTop: 12 }}>
        <button className="btn" onClick={add}>Add a treatment</button>
        <button
          className="btn pri"
          onClick={() => {
            onChange(draft.filter((r) => r.name.trim()));
            onClose();
          }}
        >
          Save plan
        </button>
        <button className="btn" onClick={onClose}>Cancel</button>
      </div>
      <div className="note" style={{ marginTop: 10 }}>
        Changing this only affects days from here on. Everything already logged keeps the plan it was scored
        against.
      </div>
    </div>
  );
}

// The bar is the control, read like a star rating: each dose in the plan is its
// own segment, and tapping one says "I have done this many". That makes every
// value reachable in a single tap in both directions, including back to nothing,
// so there is no cycling round to correct an over-tap and nothing transient to
// catch. Tapping the segment you are already on steps back off it.
//
// Extras sit underneath and only once the plan is finished, because an extra
// session is only meaningful against a full day. Keeping them off the bar is
// what lets the bar mean exactly one thing.
function DosePill({ label, count, target, onSet, valueText, allowExtra = true }) {
  const capped = Math.min(count, target);
  const extra = Math.max(0, count - target);
  const full = capped >= target;
  const pct = (capped / target) * 100;
  const say = valueText || (full ? (extra ? `Done +${extra}` : "Done") : `${capped} of ${target}`);
  // dropping below the plan drops the extras with it: an extra dose on a day you
  // did not finish is not a thing the log should be able to hold
  const setTo = (n) => onSet(n >= target ? target + extra : n);
  return (
    <div className="doserow">
      <div className={"dosepill" + (full ? " full" : "") + (extra ? " over" : "")}>
        <span className="dosefill" style={{ width: pct + "%" }} />
        <span className="lbl">{label}</span>
        <span className="val">{say}</span>
        <span className="segs">
          {Array.from({ length: target }).map((_, i) => {
            const to = i + 1 === capped ? i : i + 1;
            return (
              <button
                key={i}
                className={"seg" + (i < capped ? " on" : "")}
                onClick={() => setTo(to)}
                aria-label={`${label}, set to ${to} of ${target}`}
              />
            );
          })}
        </span>
      </div>
      {/* Beside the bar rather than under it, and only once this treatment is
          finished. A row of text links under every completed pill was four lines
          of clutter every evening to serve something used once in a while. */}
      {allowExtra && full && (
        <>
          {extra > 0 && (
            <button className="xbtn" onClick={() => onSet(count - 1)} aria-label={`One less extra ${label}`}>
              {"\u2212"}
            </button>
          )}
          <button
            className={"xbtn" + (extra ? " on" : "")}
            onClick={() => extra < 9 && onSet(count + 1)}
            disabled={extra >= 9}
            aria-label={extra ? `${extra} extra, add another` : `Record an extra ${label} session`}
            title="Extra session"
          >
            {extra ? "+" + extra : "+"}
          </button>
        </>
      )}
    </div>
  );
}

function Stepper({ count, label, target = 1, onClick }) {
  const done = count >= target;
  const cls = "tog" + (done ? " on" : count > 0 ? " part" : "") + (count > target ? " plus" : "");
  return (
    <button
      className={cls}
      onClick={onClick}
      title={target > 1 ? `${target} a day` : "Tap again for an extra session"}
    >
      <span className="box">{done ? "✓" : count > 0 ? "·" : ""}</span>
      <span>{label}</span>
      <span className="count">{target > 1 ? `${count}/${target}` : count}</span>
    </button>
  );
}

function CareRing({ n, total, size = 196 }) {
  const R = size / 2 - 16;
  const C = 2 * Math.PI * R;
  // the arc has to stay legible whether the plan is one dose or sixteen
  const SW = total > 12 ? 6 : total > 8 ? 7 : 8;
  const slot = C / Math.max(total, 1);
  const gap = Math.max(4, Math.min(14, slot * 0.16));
  const seg = Math.max(slot * 0.35, slot - gap);
  // round caps paint half a stroke past each end, so drop them once the gap cannot absorb it
  const cap = gap - SW >= 3 ? "round" : "butt";
  const cx = size / 2;
  const complete = n >= total;
  return (
    <svg className="ringsvg" width={size} height={size} viewBox={`0 0 ${size} ${size}`}
         role="img" aria-label={`${n} of ${total} daily care items done`}>
      <defs>
        <linearGradient id="careGrad" x1="0" y1="0" x2="1" y2="1">
          <stop offset="0%" stopColor="#FFFFFF" />
          <stop offset="55%" stopColor="#E4F7FF" />
          <stop offset="100%" stopColor="#9EE6FF" />
        </linearGradient>
        <filter id="careGlow" x="-60%" y="-60%" width="220%" height="220%">
          <feGaussianBlur stdDeviation="6" result="b" />
          <feMerge>
            <feMergeNode in="b" />
            <feMergeNode in="b" />
            <feMergeNode in="SourceGraphic" />
          </feMerge>
        </filter>
      </defs>

      <circle cx={cx} cy={cx} r={R - 15} fill="none" stroke="rgba(255,255,255,.14)" strokeWidth="1" />

      <g transform={`rotate(-90 ${cx} ${cx})`}>
        {Array.from({ length: total }).map((_, i) => (
          <circle
            key={"t" + i}
            cx={cx} cy={cx} r={R} fill="none" strokeWidth={SW} strokeLinecap={cap}
            stroke="rgba(255,255,255,.17)"
            strokeDasharray={`${seg} ${C - seg}`}
            strokeDashoffset={-(i * (seg + gap)) + gap / 2}
          />
        ))}
        <g filter="url(#careGlow)">
          {Array.from({ length: total }).map((_, i) =>
            i < n ? (
              <circle
                key={"f" + i}
                cx={cx} cy={cx} r={R} fill="none" strokeWidth={SW} strokeLinecap={cap}
                stroke="url(#careGrad)"
                strokeDasharray={`${seg} ${C - seg}`}
                strokeDashoffset={-(i * (seg + gap)) + gap / 2}
              />
            ) : null
          )}
        </g>
      </g>

      {complete ? (
        <>
          <text className="ring-n" x={cx} y={cx - 6} textAnchor="middle" dominantBaseline="central"
                style={{ fontSize: 34 }}>
            Done
          </text>
          <text className="ring-sub" x={cx} y={cx + 24} textAnchor="middle">
            all {total} doses
          </text>
        </>
      ) : (
        <>
          <text className="ring-n" x={cx} y={cx - 6} textAnchor="middle" dominantBaseline="central">
            {n}
            <tspan dx="2" style={{ fontSize: 19, opacity: 0.45, letterSpacing: "0.01em" }}>
              /{total}
            </tspan>
          </text>
          <text className="ring-sub" x={cx} y={cx + 26} textAnchor="middle">
            daily care
          </text>
        </>
      )}
    </svg>
  );
}

function Toggle({ on, label, onClick }) {
  return (
    <button className={"tog" + (on ? " on" : "")} onClick={onClick}>
      <span className="box">{on ? "✓" : ""}</span>
      <span>{label}</span>
    </button>
  );
}

/* ------------------------------------------------------------------ */
/*  Ribbon — the signature element                                     */
/* ------------------------------------------------------------------ */

// `flat` drops the card chrome so this can live inside the sputum card, where the
// chart belongs, instead of floating on its own at the bottom of the page.
function Ribbon({ days, span = 90, anchor, onPick, flat }) {
  const end = anchor || todayISO();
  const cells = [];
  for (let i = span - 1; i >= 0; i--) cells.push(addDays(end, -i));
  const today = todayISO();
  return (
    <div className={flat ? "ribbon-flat" : "ribbon-card"}>
     <div className={flat ? "" : "ribbon-inner"}>
      <div className="ribbon-head">
        <span className="ribbon-title">{flat ? `Last ${span} days` : `Sputum record · last ${span} days`}</span>
        <span className="ribbon-title sm">{flat ? "height is volume" : `last ${span} days · height is volume`}</span>
      </div>
      <div className="ribbon">
        {cells.map((d) => {
          const day = days[d];
          const c = day && day.sputum ? day.sputum.color : null;
          const v = day && day.sputum ? day.sputum.volume : null;
          const logged = day && (day.status || c != null);
          const h = v == null ? (logged ? 22 : 0) : 6 + (v / SCALE_MAX) * 94;
          return (
            <div
              key={d}
              className={"rib-col" + (d === today ? " rib-today" : "")}
              title={
                logged
                  ? `${fmtShort(d)} — ${c != null ? SPUTUM[c].label.replace("\n", " ") : "no sputum entry"}${
                      v != null ? ", " + VOLUME[v].toLowerCase() : ""
                    }`
                  : `${fmtShort(d)} — not logged`
              }
              onClick={() => onPick && onPick(d)}
            >
              {logged ? (
                <div
                  className="rib-fill"
                  style={{
                    height: Math.max(h, 4) + "%",
                    background: c != null ? SPUTUM[c].hex : "#C9D4DB",
                  }}
                />
              ) : (
                <div className="rib-empty" />
              )}
              {day && day.blood && day.blood !== "none" && <div className="rib-blood" />}
            </div>
          );
        })}
      </div>
      <div className="rib-axis">
        <span>{fmtShort(cells[0])}</span>
        <span>{fmtShort(cells[Math.floor(span / 2)])}</span>
        <span>Today</span>
      </div>
     </div>
    </div>
  );
}

/* ------------------------------------------------------------------ */
/*  Sputum specimen, tags, symptoms                                    */
/* ------------------------------------------------------------------ */

const RAMP = `linear-gradient(90deg, ${SPUTUM.map((x) => x.hex).join(", ")})`;

function Slider({ label, value, max, valueLabel, hint, track, thumb, onChange }) {
  return (
    <div>
      <div className="sl-head">
        <span>{label}</span>
        <b>
          {valueLabel}
          {hint ? <em>{hint}</em> : null}
        </b>
      </div>
      <input
        type="range"
        className="sl"
        min={0}
        max={max}
        step={1}
        value={value}
        style={{ "--track": track, "--thumb": thumb }}
        onChange={(e) => onChange(Number(e.target.value))}
        aria-label={label}
      />
    </div>
  );
}

function SputumPanel({ day, onChange, history, date, noted, onNote }) {
  const { color, volume, texture } = day.sputum;
  const recorded = color != null;
  const c = color ?? 0;
  const v = volume ?? 2;
  const t = texture ?? 3;

  const set = (patch) => onChange({ ...day.sputum, ...patch });

  // baseline = median colour of the last 7 recorded days before this one
  const recent = history.filter((x) => x != null).slice(-7);
  const base = recent.length >= 3 ? median(recent) : null;
  const shift = recorded && base != null ? c - base : null;

  const shade = SPUTUM[c].hex;

  return (
    <>
      <div className="spec-ctl">
          {recorded ? (
            <>
              <Slider
                label="Colour"
                value={c}
                max={7}
                valueLabel={SPUTUM[c].label.replace("\n", " ")}
                track={RAMP}
                thumb={shade}
                onChange={(n) => set({ color: n })}
              />
              <Slider
                label="Volume"
                value={v}
                max={SCALE_MAX}
                valueLabel={VOLUME[v]}
                hint={VOLUME_HINT[v]}
                track={`linear-gradient(90deg, var(--paper-2), ${shade})`}
                thumb={shade}
                onChange={(n) => set({ volume: n })}
              />
              <Slider
                label="Texture"
                value={t}
                max={SCALE_MAX}
                valueLabel={TEXTURE[t]}
                track="linear-gradient(90deg, #E9EEF3, #97A6B2)"
                thumb="#6E828C"
                onChange={(n) => set({ texture: n })}
              />
            </>
          ) : (
            <button
              className="btn pri wide"
              onClick={() => set({ color: 0, volume: 2, texture: 3 })}
            >
              Record sputum
            </button>
          )}
      </div>

      {shift != null &&
        (shift >= 2 ? (
          // only the warning gets a close; "clearing" and "in line" are not things
          // anyone needs to dismiss, and giving them one would be noise
          <Callout
            id="sputum-shift"
            sig={date + ":" + shift}
            noted={noted}
            onNote={onNote}
            cls="delta up"
          >
            {`More purulent than your recent baseline, by ${shift} steps on the scale. A sustained shift like this is the usual signal to call your team.`}
          </Callout>
        ) : (
          <div className={"delta " + (shift <= -2 ? "down" : "flat")}>
            {shift <= -2
              ? `Clearing. ${Math.abs(shift)} steps paler than your recent baseline.`
              : "In line with your recent baseline."}
          </div>
        ))}
    </>
  );
}

function ResponseProfile({ resp }) {
  if (!resp) return null;
  if (!resp.symptoms.length && resp.sputumStart == null) {
    return (
      <div className="note" style={{ marginTop: 10 }}>
        Not enough logged days across this course to read a response.
      </div>
    );
  }
  const colourMoved =
    resp.sputumStart != null && resp.sputumEnd != null && resp.sputumEnd !== resp.sputumStart;
  return (
    <div className="resp">
      {resp.symptoms.map((sy) => (
        <div className="resp-row" key={sy.key}>
          <span className="nm">{symLabel(sy.key)}</span>
          <span className={"val " + (sy.improvedDay ? "good" : "none")}>
            {sy.resolvedDay
              ? `gone by day ${sy.resolvedDay}`
              : sy.improvedDay
              ? `eased from day ${sy.improvedDay}`
              : "no change"}
          </span>
        </div>
      ))}
      {resp.sputumStart != null && (
        <div className="resp-row">
          <span className="nm">Sputum colour</span>
          <span className={"val " + (colourMoved && resp.sputumEnd < resp.sputumStart ? "good" : "none")}>
            {colourMoved
              ? `${SPUTUM[resp.sputumStart].short.toLowerCase()} to ${SPUTUM[resp.sputumEnd].short.toLowerCase()}`
              : "unchanged"}
          </span>
        </div>
      )}
      {resp.loggedDays < resp.windowDays && (
        <div className="note" style={{ marginTop: 10 }}>
          Read from {resp.loggedDays} of {resp.windowDays} days. Unlogged days are skipped, so a symptom may have
          turned earlier than shown.
        </div>
      )}
    </div>
  );
}

function PrnRow({ day, meds, onSet, onAdd, onDelete }) {
  const [adding, setAdding] = useState(false);
  const [editing, setEditing] = useState(false);
  const [text, setText] = useState("");
  const prn = day.prn || {};
  const commit = () => {
    const v = text.trim();
    if (v) onAdd(v);
    setText("");
    setAdding(false);
  };
  return (
    <>
      <div className="chips">
        {meds.map((m) => {
          const n = prn[m] || 0;
          return (
            <button
              key={m}
              className={"chip" + (!editing && n > 0 ? " on" : "")}
              onClick={() => (editing ? onDelete(m) : onSet(m, (n + 1) % 5))}
            >
              {m}
              {editing ? "  \u00d7" : n > 0 ? "  \u00d7" + n : ""}
            </button>
          );
        })}
        {!adding && !editing && (
          <button className="chip add" onClick={() => setAdding(true)}>
            + New
          </button>
        )}
        {onDelete && meds.length > 0 && !adding && (
          <button className="chip add" onClick={() => setEditing((v) => !v)}>
            {editing ? "Done" : "Edit list"}
          </button>
        )}
      </div>
      {editing && (
        <div className="note" style={{ marginTop: 10 }}>
          Tap one to drop it from the list. Days you already recorded it on keep their record.
        </div>
      )}
      {adding && (
        <div className="chipwrap">
          <input
            className="inp"
            autoFocus
            placeholder="Paracetamol, antihistamine, honey"
            value={text}
            onChange={(e) => setText(e.target.value)}
            onKeyDown={(e) => e.key === "Enter" && commit()}
          />
          <button className="btn pri" onClick={commit}>Add</button>
        </div>
      )}
    </>
  );
}

function TagPicker({ selected, all, onToggle, onCreate, onDelete }) {
  const [adding, setAdding] = useState(false);
  const [editing, setEditing] = useState(false);
  const [text, setText] = useState("");
  const commit = () => {
    const v = text.trim();
    if (v) onCreate(v);
    setText("");
    setAdding(false);
  };
  const ordered = [...all].sort((a, b) => {
    const sa = selected.includes(a) ? 0 : 1;
    const sb = selected.includes(b) ? 0 : 1;
    return sa - sb;
  });
  return (
    <>
      <div className="chips">
        {ordered.map((t) => (
          <button
            key={t}
            className={"chip" + (!editing && selected.includes(t) ? " on" : "")}
            onClick={() => (editing ? onDelete(t) : onToggle(t))}
          >
            {t}
            {editing ? "  \u00d7" : ""}
          </button>
        ))}
        {!adding && !editing && (
          <button className="chip add" onClick={() => setAdding(true)}>
            + New tag
          </button>
        )}
        {all.length > 0 && !adding && (
          <button className="chip add" onClick={() => setEditing((v) => !v)}>
            {editing ? "Done" : "Edit list"}
          </button>
        )}
      </div>
      {editing && (
        <div className="note" style={{ marginTop: 10 }}>
          Tap a tag to remove it from the list. Days already tagged with it keep their record.
        </div>
      )}
      {adding && (
        <div className="chipwrap">
          <input
            className="inp"
            autoFocus
            placeholder="Name it"
            value={text}
            onChange={(e) => setText(e.target.value)}
            onKeyDown={(e) => e.key === "Enter" && commit()}
          />
          <button className="btn pri" onClick={commit}>
            Add
          </button>
        </div>
      )}
    </>
  );
}

function SymptomList({ day, custom, onSet, onAddCustom, onDeleteCustom }) {
  const [adding, setAdding] = useState(false);
  const [editing, setEditing] = useState(false);
  const [text, setText] = useState("");
  const rows = [...SYMPTOMS.map((x) => x[0]), ...custom.map((n) => "c:" + n)];
  const reviewed = day.symptomsReviewed !== false;

  return (
    <>
      {rows.map((k) => {
        const cur = day.symptoms[k] ?? 0;
        // only the ones you added yourself can go; the six standard features are what
        // the exacerbation count is defined on
        const mine = k.indexOf("c:") === 0;
        return (
          <div className="sym" key={k}>
            <span className="nm">{symLabel(k)}</span>
            {editing && mine ? (
              <button
                className="iconsm del"
                aria-label={"Remove " + symLabel(k)}
                onClick={() => onDeleteCustom(k.slice(2))}
              >
                {"×"}
              </button>
            ) : null}
            <div className="dots">
              {[0, 1, 2, 3].map((lv) => (
                <button
                  key={lv}
                  className={"dot" + (cur === lv ? " on lv" + lv : "")}
                  onClick={() => onSet(k, lv)}
                  aria-label={`${symLabel(k)} ${SEV[lv]}`}
                >
                  {SEV_MARK[lv]}
                </button>
              ))}
            </div>
          </div>
        );
      })}
      {!adding ? (
        <div className="chips" style={{ marginTop: 12 }}>
          <button className="chip add" onClick={() => setAdding(true)}>
            + Add a symptom
          </button>
          {onDeleteCustom && custom.length > 0 && (
            <button className="chip add" onClick={() => setEditing((v) => !v)}>
              {editing ? "Done" : "Edit list"}
            </button>
          )}
        </div>
      ) : (
        <div className="chipwrap">
          <input
            className="inp"
            autoFocus
            placeholder="Night sweats, appetite, headache"
            value={text}
            onChange={(e) => setText(e.target.value)}
            onKeyDown={(e) => {
              if (e.key === "Enter" && text.trim()) {
                onAddCustom(text.trim());
                setText("");
                setAdding(false);
              }
            }}
          />
          <button
            className="btn pri"
            onClick={() => {
              if (text.trim()) onAddCustom(text.trim());
              setText("");
              setAdding(false);
            }}
          >
            Add
          </button>
        </div>
      )}
      {!reviewed && (
        <div className="note" style={{ marginTop: 12 }}>
          Not reviewed yet, so this day stays out of the trend charts.
        </div>
      )}
    </>
  );
}

/* ------------------------------------------------------------------ */
/*  Header: week strip, status fork, hero, glass stats                 */
/* ------------------------------------------------------------------ */

const DOW = ["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"];

function WeekStrip({ date, setDate, days, weekEnd }) {
  const today = todayISO();
  const cells = [];
  for (let i = 6; i >= 0; i--) cells.push(addDays(weekEnd, -i));
  return (
   <div className="weekrow">
    <button className="wnav" aria-label="Previous week" onClick={() => setDate(addDays(date, -7))}>
      {"\u2039"}
    </button>
    <div className="week" style={{ flex: 1, marginTop: 0 }}>
      {cells.map((d) => {
        const day = days[d];
        const cls =
          "wd" +
          (d === date ? " on" : "") +
          (day && day.status ? " has" : "") +
          (day && day.status === "unwell" ? " ill" : "");
        return (
          <button
            key={d}
            className={cls}
            disabled={d > today}
            onClick={() => setDate(d)}
            aria-label={fmtLong(d)}
          >
            <span className="dow">{DOW[parseISO(d).getDay()]}</span>
            <span className="num">{parseISO(d).getDate()}</span>
            <span className="mark" />
          </button>
        );
      })}
    </div>
    <button
      className="wnav"
      aria-label="Next week"
      disabled={addDays(date, 7) > today}
      onClick={() => setDate(addDays(date, 7) > today ? today : addDays(date, 7))}
    >
      {"\u203a"}
    </button>
   </div>
  );
}

// Clouds built from fractal turbulence rather than blurred ovals: the colour matrix
// pulls an alpha channel out of the noise, which gives wispy edges and real silhouettes.
function CloudSheet({ id, seed, freq, cut, gain }) {
  return (
    <svg viewBox="0 0 640 320" preserveAspectRatio="none" aria-hidden="true">
      <defs>
        <filter id={id} x="-6%" y="-6%" width="112%" height="112%" colorInterpolationFilters="sRGB">
          <feTurbulence type="fractalNoise" baseFrequency={freq} numOctaves="5" seed={seed} stitchTiles="stitch" result="n" />
          <feColorMatrix
            in="n"
            type="matrix"
            values={`0 0 0 0 0.93  0 0 0 0 0.97  0 0 0 0 1  ${gain} 0 0 0 ${cut}`}
          />
        </filter>
      </defs>
      <rect width="640" height="320" filter={`url(#${id})`} />
    </svg>
  );
}

function CloudLayer({ cls, id, seed, freq, cut, gain }) {
  return (
    <div className={"cl " + cls}>
      <div className="cl-bob">
        <CloudSheet id={id} seed={seed} freq={freq} cut={cut} gain={gain} />
      </div>
    </div>
  );
}

function MonthPanel({ days, date, setDate, onClose, regimen }) {
  const [cursor, setCursor] = useState(date.slice(0, 7));
  const today = todayISO();
  const [y, m] = cursor.split("-").map(Number);
  const first = new Date(y, m - 1, 1);
  const startPad = first.getDay();
  const daysIn = new Date(y, m, 0).getDate();
  const shift = (n) => {
    const d = new Date(y, m - 1 + n, 1);
    setCursor(iso(d).slice(0, 7));
  };
  const cells = [];
  for (let i = 0; i < startPad; i++) cells.push(null);
  for (let i = 1; i <= daysIn; i++) cells.push(`${cursor}-${String(i).padStart(2, "0")}`);

  const logged = cells.filter((c) => c && days[c] && days[c].status).length;
  const cared = cells.filter((c) => c && careComplete(days[c], regimen)).length;

  // Drag the grid sideways to change month. The page's own day-swipe is disabled
  // while this panel is open, so the axis is ours and nothing has to be shared.
  const atLatest = cursor >= today.slice(0, 7);
  const grab = useRef(null);
  const gridRef = useRef(null);
  const [dx, setDx] = useState(0);
  const [glide, setGlide] = useState(false);
  const start = (e) => {
    const t = e.touches && e.touches[0];
    if (!t) return;
    grab.current = { x: t.clientX, y: t.clientY, axis: null, at: Date.now() };
    setGlide(false);
  };
  const move = (e) => {
    const g = grab.current;
    const t = e.touches && e.touches[0];
    if (!g || !t) return;
    const ax = t.clientX - g.x;
    const ay = t.clientY - g.y;
    if (g.axis === null) {
      if (Math.abs(ax) < 8 && Math.abs(ay) < 8) return;
      g.axis = Math.abs(ax) > Math.abs(ay) * 1.2 ? "x" : "y";
      if (g.axis === "y") {
        grab.current = null;
        return;
      }
    }
    // no month after this one, so dragging forward drags heavy
    setDx(ax < 0 && atLatest ? ax * 0.25 : ax);
  };
  const end = () => {
    const g = grab.current;
    grab.current = null;
    setGlide(true);
    if (!g || g.axis !== "x") return setDx(0);
    const w = (gridRef.current && gridRef.current.offsetWidth) || 320;
    const far = Math.abs(dx) > Math.min(84, w * 0.26);
    const flick = Date.now() - g.at < 320 && Math.abs(dx) > 38;
    const forward = dx < 0;
    if ((far || flick) && !(forward && atLatest)) shift(forward ? 1 : -1);
    setDx(0);
  };

  return (
    <div className="card cal">
      <div className="cal-head">
        <button className="btn sm" onClick={() => shift(-1)}>{"\u2039"}</button>
        <span className="m">
          {first.toLocaleDateString(undefined, { month: "long", year: "numeric" })}
        </span>
        <div style={{ display: "flex", gap: 7 }}>
          <button className="btn sm" disabled={cursor >= today.slice(0, 7)} onClick={() => shift(1)}>
            {"\u203a"}
          </button>
          <button className="btn sm" onClick={onClose}>Close</button>
        </div>
      </div>

      <div className="cal-dow">
        {["S", "M", "T", "W", "T", "F", "S"].map((d, i) => (
          <span key={i}>{d}</span>
        ))}
      </div>

      <div
        className="cal-grid"
        ref={gridRef}
        onTouchStart={start}
        onTouchMove={move}
        onTouchEnd={end}
        onTouchCancel={end}
        style={{
          transform: dx ? `translate3d(${dx}px,0,0)` : undefined,
          opacity: dx ? Math.max(0.45, 1 - Math.abs(dx) / 420) : undefined,
          transition: glide ? "transform .2s var(--ease), opacity .2s var(--ease)" : "none",
        }}
      >
        {cells.map((c, i) => {
          if (!c) return <div className="cal-cell blank" key={"b" + i} />;
          const day = days[c];
          const col = day && day.sputum ? day.sputum.color : null;
          const cls =
            "cal-cell" +
            (c > today ? " future" : "") +
            (day && day.status === "unwell" ? " ill" : "") +
            (c === date ? " sel" : "");
          return (
            <button
              key={c}
              className={cls}
              disabled={c > today}
              onClick={() => {
                setDate(c);
                onClose();
              }}
            >
              {col != null && (
                <span className="bg" style={{ background: SPUTUM[col].hex, opacity: 0.75 }} />
              )}
              <span className="n">{Number(c.slice(-2))}</span>
              {careComplete(day, regimen) && <span className="care" />}
              {day && day.blood && day.blood !== "none" && <span className="blood" />}
            </button>
          );
        })}
      </div>

      <div className="cal-legend">
        <span><b style={{ background: "var(--lime)" }} />care complete</span>
        <span><b style={{ boxShadow: "inset 0 0 0 1.5px var(--sky-2)", background: "none" }} />unwell</span>
        <span><b style={{ background: "var(--alarm)", borderRadius: "50%" }} />blood</span>
      </div>
      <div className="note" style={{ marginTop: 10 }}>
        {logged} days logged this month, {cared} with all four doses in.
      </div>
    </div>
  );
}

function Milestone({ value, run, onDismiss }) {
  return (
    <div className="milestone">
      <div className="n">{value}</div>
      <div className="t">days clear</div>
      <div className="d">
        {run.isBest
          ? "The longest run you have on record. Whatever you have been doing these past few months, this is it working."
          : `Past the ${value} day mark. Your best run so far is ${run.best} days.`}
      </div>
      <button className="btn" onClick={onDismiss}>
        Thanks
      </button>
    </div>
  );
}

function StatusFork({ day, onWell, onIll, onClear }) {
  const st = day ? day.status : null;
  return (
    <div className="pillbar">
      <button
        className={st === "well" ? "on" : ""}
        onClick={() => (st === "well" ? onClear() : onWell())}
      >
        Well
      </button>
      <button
        className={st === "unwell" ? "on ill" : ""}
        onClick={() => (st === "unwell" ? onClear() : onIll())}
      >
        Unwell
      </button>
    </div>
  );
}

function statusLine(episodes, days, date) {
  const today = todayISO();
  const last = episodes.length ? episodes[episodes.length - 1] : null;
  const todayStatus = days[today] ? days[today].status : null;
  if (last && todayStatus === "unwell")
    return { n: diffDays(last.start, today) + 1, text: "day of this episode" };
  if (last) {
    const n = diffDays(last.end, today);
    return { n, text: n === 1 ? "day since the last episode" : "days since the last episode" };
  }
  return null;
}

// `compact` is the daily screen: the ring stays, because today's doses are the thing
// you can still act on, and the run of clear days moves to History where the slower
// numbers live. It was taking the space the day's actual work needed.
function Hero({ episodes, days, date, run, care, regimen, compact }) {
  const n = doseCount(days[date], regimen);
  const total = Math.max(doseTotal(planOf(days[date], regimen)), 1);
  const st = statusLine(episodes, days, date);
  const pct = Math.min((run.current / run.target) * 100, 100);
  return (
    <div className="ringwrap">
      <CareRing n={n} total={total} size={compact ? 156 : 196} />
      <div className="ring-cap">
        {st ? (
          <>
            <b>{st.n}</b> {st.text}
          </>
        ) : (
          "Mark today well or unwell to start tracking episodes"
        )}
      </div>
      {compact && care.hasPlan && care.current > 0 && (
        <div className="run">
          <div className={"run-bar" + (care.best > 0 && care.current >= care.best ? " best" : "")}>
            <span style={{ width: Math.min((care.current / Math.max(care.best, 7)) * 100, 100) + "%" }} />
          </div>
          <div className="run-lab">
            <span>
              <b>{care.current}</b> {care.current === 1 ? "day" : "days"} of care in a row
            </span>
            <span className={care.best > 0 && care.current >= care.best ? "pb" : ""}>
              {care.best > 0 && care.current >= care.best ? "your best yet" : care.best ? `best ${care.best}` : ""}
            </span>
          </div>
        </div>
      )}
      {!compact && run.current > 0 && (
        <div className="run">
          <div className={"run-bar" + (run.isBest ? " best" : "")}>
            <span style={{ width: pct + "%" }} />
          </div>
          <div className="run-lab">
            <span>
              <b>{run.current}</b> days clear
            </span>
            <span className={run.isBest ? "pb" : ""}>
              {run.isBest ? "personal best" : run.best ? `best ${run.best}` : `first ${run.target}`}
            </span>
          </div>
        </div>
      )}
    </div>
  );
}

function GlassStats({ days, date, regimen }) {
  const today = todayISO();
  const day = days[date];
  const c = day && day.sputum ? day.sputum.color : null;

  let week7 = 0;
  for (let i = 0; i < 7; i++) if (careComplete(days[addDays(today, -i)], regimen)) week7++;

  const pfKeys = Object.keys(days)
    .filter((k) => days[k].peakFlow !== "" && !isNaN(parseFloat(days[k].peakFlow)))
    .sort();
  const lastPf = pfKeys.length ? pfKeys[pfKeys.length - 1] : null;
  const pfAge = lastPf ? diffDays(lastPf, today) : null;

  return (
    <div className="glass">
      <div className="gcard">
        <div className="k">Sputum</div>
        <div className="v">
          {c != null ? (
            <>
              <span className="gswatch" style={{ background: SPUTUM[c].hex }} />
              <span style={{ fontSize: 13 }}>{SPUTUM[c].short}</span>
            </>
          ) : (
            <span style={{ opacity: 0.55 }}>—</span>
          )}
        </div>
      </div>
      <div className="gcard">
        <div className="k">7-day care</div>
        <div className="v">
          {week7}
          <small>of 7</small>
        </div>
      </div>
      <div className="gcard">
        <div className="k">Peak flow</div>
        <div className="v">
          {lastPf ? (
            <>
              {days[lastPf].peakFlow}
              <small>{pfAge === 0 ? "today" : pfAge + "d ago"}</small>
            </>
          ) : (
            <span style={{ opacity: 0.55 }}>—</span>
          )}
        </div>
      </div>
    </div>
  );
}

/* ------------------------------------------------------------------ */
/*  Today view                                                         */
/* ------------------------------------------------------------------ */

function TodayView({ state, episodes, setDay, date, setDate, addCourse, endCourse, deleteCourse, editCourse, setCourseDose, onSetup, addTag, addCustomSymptom, deleteCustomSymptom, setStatus, clearDay, onShareEpisode, deleteTag, addPrnMed, deletePrnMed, addCustomDrug, deleteCustomDrug, setCourseOutcome, setCourseNote, addLocation, setAqi, setRegimen, setTab, setRescue, setQuestions, onDismissWarning, onFold, onNote }) {
  const day = state.days[date] || emptyDay();
  const isUnwell = day.status === "unwell";
  const logged = !!day.status;
  const sputumRecorded = day.sputum.color != null;

  // How much is in each foldable section today. It doubles as the hint on a
  // rolled-up heading and as the fallback for whether to roll it up at all.
  const symptomsLogged = Object.values(day.symptoms || {}).filter((v) => v > 0).length;
  const vitalsLogged = ["peakFlow", "fev1", "spo2", "temp", "restHr", "weight"].filter(
    (k) => day[k] !== "" && day[k] != null
  ).length + (day.mmrc != null ? 1 : 0);
  const foldOpen = (id, fallback) => {
    const f = (state.folds || {})[id];
    return f === undefined ? fallback : f;
  };
  const setFold = (id, open) => onFold(id, open);


  const [showCourse, setShowCourse] = useState(false);
  const [editCourseId, setEditCourseId] = useState(null);
  const [pausing, setPausing] = useState(false);
  const [showDetail, setShowDetail] = useState(false);
  const [showNote, setShowNote] = useState(false);
  const [showTags, setShowTags] = useState(false);
  const [changeDose, setChangeDose] = useState(false);
  const [onsetDate, setOnsetDate] = useState("");
  const [editPlan, setEditPlan] = useState(false);
  const [backupSnoozed, setBackupSnoozed] = useState(false);
  const apptDays = state.appt && state.appt.date ? diffDays(todayISO(), state.appt.date) : null;
  const apptSoon = apptDays != null && apptDays >= 0 && apptDays <= 7 && date === todayISO();
  const openQuestions = (state.questions || []).filter((q) => !q.done).length;

  const backupLast = lastBackupAt();
  const backupAge = backupLast ? diffDays(backupLast, todayISO()) : null;
  const backupDue =
    !backupSnoozed &&
    date === todayISO() &&
    Object.keys(state.days).length >= 10 &&
    (backupAge == null ? Object.keys(state.days).length >= 5 : backupAge >= 30);

  const up = (patch) => setDay(date, { ...day, ...patch });
  const todayPlan = planOf(day, state.regimen);
  const planTotal = doseTotal(todayPlan);
  const setCare = (k, n) =>
    up({ care: { ...day.care, [k]: Math.max(0, n) }, plan: day.plan || todayPlan });
  const upSym = (k, v) => up({ symptoms: { ...day.symptoms, [k]: v }, symptomsReviewed: true });
  const upTag = (t) => {
    const cur = day.tags || [];
    up({ tags: cur.includes(t) ? cur.filter((x) => x !== t) : [...cur, t] });
  };

  const sputumHistory = useMemo(
    () =>
      Object.keys(state.days)
        .filter((k) => k < date && state.days[k].sputum && state.days[k].sputum.color != null)
        .sort()
        .map((k) => state.days[k].sputum.color),
    [state.days, date]
  );

  const careDone = doseCount(day, state.regimen);
  const tracks = (k) => (state.track || {})[k] !== false;
  const anyVital = ["peakFlow", "fev1", "spo2", "temp", "restHr", "weight", "mmrc"].some(tracks);
  // what is left of the plan today, by name, for the prompt at the foot of the page
  const careLeft = todayPlan
    .map((r) => ({ name: r.name, left: Math.max(0, r.target - (day.care[r.id] || 0)) }))
    .filter((r) => r.left > 0);

  const rules = useMemo(() => exacerbationRules(day, state.conditions), [day, state.conditions]);
  const exac = rules[0] || { n: 0, met: false, list: [] };

  // keep the picker sane if the selected day changes underneath it
  const onsetPick =
    onsetDate && onsetDate < date && diffDays(onsetDate, date) <= 120 ? onsetDate : addDays(date, -1);

  const prevDay = state.days[addDays(date, -1)];
  const showOnsetPrompt = isUnwell && (!prevDay || prevDay.status !== "unwell") && !day.onsetChecked;

  const activeCourses = (state.courses || []).filter((c) => {
    const ce = c.days ? addDays(c.startDate, c.days - 1) : null;
    return c.startDate <= date && (!ce || ce >= date);
  });

  const finishedCourses = (state.courses || []).filter((c) => {
    if (!c.days || c.outcome) return false;
    const ce = addDays(c.startDate, c.days - 1);
    return ce < date && diffDays(ce, date) <= 14;
  });

  const lastPF = useMemo(() => {
    const keys = Object.keys(state.days)
      .filter((k) => state.days[k].peakFlow !== "" && state.days[k].peakFlow != null)
      .sort();
    return keys.length ? keys[keys.length - 1] : null;
  }, [state.days]);
  const pfDue =
    date === todayISO() && (!lastPF || diffDays(lastPF, date) >= 7) && !day.peakFlow && !day.pfSnoozed;

  // one silent attempt per day; if the sandbox blocks it the card offers manual entry
  const tried = useRef({});
  useEffect(() => {
    if (date !== todayISO() || day.aqi || tried.current[date]) return;
    const loc = (state.locations || [])[0];
    if (!loc) return;
    tried.current[date] = true;
    let live = true;
    getAqi(loc, date)
      .then((r) => {
        if (live) setAqi(date, { ...r, location: loc.name, at: new Date().toISOString() });
      })
      .catch(() => {});
    return () => {
      live = false;
    };
  }, [date, day.aqi]);

  /* ---------------- sections ---------------- */

  // Courses with a daily frequency are tickable; the count stays separate from the
  // care ring even though they now share a card, because doseCount walks the regimen.
  const doseTakers = activeCourses.filter((c) => c.freq > 0);
  // Pausing is the same `active` flag the plan editor sets. A paused treatment leaves
  // today's target, so it is not recorded as a dose you missed, and every day already
  // logged keeps the plan it was scored against.
  const pausedPlan = (state.regimen || []).filter((r) => !r.active && r.name);
  const setTreatmentPaused = (id, isPaused) =>
    setRegimen((state.regimen || []).map((r) => (r.id === id ? { ...r, active: !isPaused } : r)));

  const careSection = (
    <div className="card">
      <div className="card-t">
        <span>Today's care</span>
        <button className="btn sm" onClick={() => setEditPlan((v) => !v)}>
          {editPlan ? "Close" : "Edit plan"}
        </button>
      </div>

      {editPlan ? (
        <PlanEditor regimen={state.regimen || []} onChange={setRegimen} onClose={() => setEditPlan(false)} />
      ) : (
        <>
          {todayPlan.length === 0 && pausedPlan.length === 0 && (
            <>
              <div className="note">Nothing in your plan yet.</div>
              <button className="btn pri wide" style={{ marginTop: 12 }} onClick={onSetup}>
                Set up my daily care
              </button>
            </>
          )}
          {doseTakers.length > 0 && todayPlan.length > 0 && (
            <div className="rowlab" style={{ marginTop: 0 }}>Your plan</div>
          )}
          {todayPlan.map((r) => (
            <DosePill
              key={r.id}
              label={r.name}
              target={r.target}
              count={day.care[r.id] || 0}
              onSet={(n) => setCare(r.id, n)}
            />
          ))}
          {careDone >= planTotal && planTotal > 0 ? (
            <div className="done-flag">
              <span className="tick">{"\u2713"}</span>
              Your plan is done for today
            </div>
          ) : (
            planTotal > 0 && (
              <div className="note" style={{ marginTop: 12 }}>
                Tap along the bar to set how many doses you have done. Tap where you are to take one back. A
                finished treatment gets a + beside it for an extra session.
              </div>
            )
          )}


          {/* Pausing sets the same active flag the plan editor uses, so a paused
              treatment drops out of today's target instead of counting against you,
              and days already logged keep the plan they were scored on. */}
          {pausedPlan.length > 0 && (
            <>
              <div className="rowlab">Paused</div>
              <div className="chips">
                {pausedPlan.map((r) => (
                  <button key={r.id} className="chip" onClick={() => setTreatmentPaused(r.id, false)}>
                    {r.name}
                    {"  \u21ba"}
                  </button>
                ))}
              </div>
            </>
          )}
          {todayPlan.length > 0 && (
            <div className="chips" style={{ marginTop: 10 }}>
              <button className="chip add" onClick={() => setPausing((v) => !v)}>
                {pausing ? "Done" : "Pause a treatment"}
              </button>
            </div>
          )}
          {pausing && (
            <>
              <div className="chips" style={{ marginTop: 8 }}>
                {todayPlan.map((r) => (
                  <button key={r.id} className="chip" onClick={() => setTreatmentPaused(r.id, true)}>
                    {r.name}
                    {"  \u23f8"}
                  </button>
                ))}
              </div>
              <div className="note" style={{ marginTop: 10 }}>
                For something you have been told to stop for a while. It comes off today's total
                rather than counting as a missed dose.
              </div>
            </>
          )}

          {doseTakers.length > 0 && (
            <>
              <div className="rowlab">
                Medication course
                <Info title="Medication doses">
                  <p>Tick off each dose of a course as you take it.</p>
                  <p>
                    These are counted on their own, apart from your care plan. Putting them together
                    would change what the ring has meant on every day you have already logged.
                  </p>
                  <p>When a course finishes it reports how many of its doses you ticked off.</p>
                </Info>
              </div>
              {doseTakers.map((c) => (
                <div key={c.id}>
                  <DosePill
                    label={c.drug}
                    target={c.freq}
                    count={(day.courseDoses || {})[c.id] || 0}
                    onSet={(n) => setCourseDose(date, c.id, n)}
                    allowExtra={false}
                  />
                  {c.note ? <div className="note dosenote">{c.note}</div> : null}
                </div>
              ))}
            </>
          )}

          <div className="rowlab">Taken as needed</div>
          <PrnRow
            day={day}
            meds={state.prnMeds || []}
            onSet={(m, n) => up({ prn: { ...(day.prn || {}), [m]: n } })}
            onAdd={addPrnMed}
            onDelete={deletePrnMed}
          />
        </>
      )}
    </div>
  );

  const airSection = (
    <AirQuality
      day={day}
      date={date}
      locations={state.locations || []}
      onSet={(a) => setAqi(date, a)}
      onAddLocation={addLocation}
    />
  );

  const sputumSection = (
    <div className="card">
      <div className="card-t">
        <span>Sputum</span>
        <span className="hint">drag to match</span>
      </div>
      <SputumPanel
        day={day}
        history={sputumHistory}
        date={date}
        noted={state.noted}
        onNote={onNote}
        onChange={(sp) => up({ sputum: sp })}
      />

      {sputumRecorded && (
        <>
          <div className="rowlab">Any blood in it</div>
          <Seg
            options={[
              { v: "none", label: "No" },
              { v: "yes", label: "Yes" },
            ]}
            value={day.blood === "none" ? "none" : day.blood ? "yes" : null}
            onChange={(v) => up({ blood: v === "yes" ? "streaks" : v })}
            small
            alarm={!!day.blood && day.blood !== "none"}
          />
          {day.blood && day.blood !== "none" && (
            <>
              <Seg
                options={[
                  { v: "streaks", label: "Streaks" },
                  { v: "frank", label: "Frank blood" },
                ]}
                value={day.blood}
                onChange={(v) => up({ blood: v || "streaks" })}
                small
                alarm
              />
              {day.blood === "frank" && (
                <div className="banner red">
                  Frank blood is worth a same-day call to your respiratory team, not a wait and see.
                </div>
              )}
            </>
          )}
        </>
      )}
      <Ribbon days={state.days} span={90} flat onPick={(d) => setDate(d)} />
    </div>
  );

  const symptomSection = (
    <div className="card">
      <Fold
        id="symptoms"
        open={foldOpen("symptoms", isUnwell || symptomsLogged > 0)}
        onToggle={setFold}
        title="Symptoms"
        hint={symptomsLogged ? `${symptomsLogged} logged` : "none · mild · moderate · severe"}
        info={
          <Info title="Symptoms">
            <p>Set each one to none, mild, moderate or severe.</p>
            <p>
              A day you have not touched is left out of the trend charts rather than counted as a day with nothing
              wrong. Not filling the list in and having no symptoms are different things, and the charts would
              otherwise read them the same way.
            </p>
            <p>Six of these are the standard exacerbation features, which the app counts for you.</p>
          </Info>
        }
      >
        <SymptomList
          day={day}
          custom={state.customSymptoms || []}
          onSet={upSym}
          onAddCustom={addCustomSymptom}
          onDeleteCustom={deleteCustomSymptom}
        />
      </Fold>
      {/* the exacerbation count sits outside the fold on purpose: it is the one
          thing on this card you must not be able to roll away out of sight */}
      {rules.filter((r) => r.met).map((r) => (
        // keyed on the day and the count, so closing it acknowledges today at this
        // many features; one more feature, or tomorrow, and it is back
        <Callout
          key={r.key}
          id={"exac-" + r.key}
          sig={date + ":" + r.n}
          noted={state.noted}
          onNote={onNote}
          cls="banner"
        >
          {r.key === "copd" ? (
            <>
              {r.n} of the 3 COPD exacerbation criteria are present today ({r.list.join(", ")}). Two or more is the
              usual threshold for ringing your team. This counts what you logged. It is not a diagnosis.
            </>
          ) : (
            <>
              {r.n} of the 6 standard exacerbation features are present today ({r.list.join(", ")}). Three or more
              sustained over 48 hours is the usual threshold for ringing your team rather than waiting it out. This
              counts what you logged. It is not a diagnosis.
            </>
          )}
        </Callout>
      ))}
      {(state.conditions || []).indexOf("cf") !== -1 && (
        <div className="note" style={{ marginTop: 10 }}>
          Cystic fibrosis exacerbations are judged on more than symptoms — lung function, weight and
          sinus signs among them — so no count is shown for it here.
        </div>
      )}
    </div>
  );

  const cultureSection = (
    <div className="card">
      <div className="card-t">
        <span>Sputum culture</span>
        <span className="hint">what grew, and when</span>
      </div>
      <Toggle
        on={day.sampleSent}
        label="Sample sent to the lab"
        onClick={() => up({ sampleSent: !day.sampleSent })}
      />
      {(day.sampleSent || day.organism) && (
        <>
          <div className="rowlab">Result</div>
          <select className="inp" value={day.organism} onChange={(e) => up({ organism: e.target.value })}>
            {ORGANISMS.map((o) => (
              <option key={o} value={o}>
                {o || "Not back yet"}
              </option>
            ))}
          </select>
        </>
      )}
    </div>
  );

  const detailSection = (
    <>
      {anyVital && (
      <div className="card">
        <Fold
          id="vitals"
          open={foldOpen("vitals", vitalsLogged > 0)}
          onToggle={setFold}
          title="Measurements"
          hint={vitalsLogged ? `${vitalsLogged} recorded` : "blank if not taken"}
        >
        <div className="vitals">
          {tracks("peakFlow") && (
            <div className="vit">
              <label>Peak flow L/min</label>
              <input type="number" inputMode="numeric" placeholder="—" value={day.peakFlow}
                onChange={(e) => up({ peakFlow: e.target.value })} />
            </div>
          )}
          {tracks("spo2") && (
            <div className="vit">
              <label>SpO₂ %</label>
              <input type="number" inputMode="numeric" placeholder="—" value={day.spo2}
                onChange={(e) => up({ spo2: e.target.value })} />
            </div>
          )}
          {tracks("temp") && (
            <div className="vit">
              <label>Temp °C</label>
              <input type="number" inputMode="decimal" step="0.1" placeholder="—" value={day.temp}
                onChange={(e) => up({ temp: e.target.value })} />
            </div>
          )}
          {tracks("restHr") && (
            <div className="vit">
              <label>Resting HR</label>
              <input type="number" inputMode="numeric" placeholder="—" value={day.restHr}
                onChange={(e) => up({ restHr: e.target.value })} />
            </div>
          )}
          {tracks("fev1") && (
            <div className="vit">
              <label>FEV1 L</label>
              <input type="number" inputMode="decimal" step="0.01" placeholder="—" value={day.fev1}
                onChange={(e) => up({ fev1: e.target.value })} />
            </div>
          )}
          {tracks("weight") && (
            <div className="vit">
              <label>Weight {state.weightUnit === "lb" ? "lb" : "kg"}</label>
              <input type="number" inputMode="decimal" step="0.1" placeholder="—" value={day.weight}
                onChange={(e) => up({ weight: e.target.value })} />
            </div>
          )}
        </div>
        {tracks("mmrc") && (
          <>
            <div className="rowlab">
              Breathlessness grade
              <Info title="Breathlessness grade">
                <p>The MRC scale. It asks what you can usually manage, not how today feels.</p>
                <p><strong>0</strong> — only breathless with hard exercise.</p>
                <p><strong>1</strong> — short of breath hurrying, or up a slight hill.</p>
                <p><strong>2</strong> — slower than others your age on the flat, or stopping for breath.</p>
                <p><strong>3</strong> — stopping after a hundred metres or a few minutes on the flat.</p>
                <p><strong>4</strong> — too breathless to leave the house, or breathless dressing.</p>
                <p>
                  It moves over months rather than days, so there is no need to set it often. The
                  daily breathlessness in your symptoms is the one that asks about today.
                </p>
              </Info>
            </div>
            <Seg options={MMRC} value={day.mmrc || null} onChange={(v) => up({ mmrc: v })} small />
          </>
        )}
        <OtherInsights day={day} days={state.days} date={date} />
        {tracks("peakFlow") && date !== todayISO() && day.peakFlow !== "" && (
          <PeakFlowInsight days={state.days} date={date} value={day.peakFlow} />
        )}
        </Fold>
      </div>
      )}

      <div className="card">
        <div className="card-t">
          <span>Medication courses</span>
          <button className="btn sm" onClick={() => setShowCourse((v) => !v)}>
            {showCourse ? "Close" : "Start a course"}
          </button>
        </div>
        {showCourse && (
          <CourseForm
            date={date}
            customDrugs={state.customDrugs || []}
            onRemember={addCustomDrug}
            onForgetDrug={deleteCustomDrug}
            onCancel={() => setShowCourse(false)}
            onAdd={(c) => {
              addCourse(c);
              setShowCourse(false);
            }}
          />
        )}
        {activeCourses.length === 0 && finishedCourses.length === 0 && !showCourse && (
          <div className="note">Nothing active on this date.</div>
        )}
        {activeCourses.map((c) =>
          editCourseId === c.id ? (
            <CourseForm
              key={c.id}
              date={date}
              course={c}
              customDrugs={state.customDrugs || []}
              onForgetDrug={deleteCustomDrug}
              onRemember={addCustomDrug}
              onCancel={() => setEditCourseId(null)}
              onAdd={(next) => {
                editCourse(c.id, {
                  drug: next.drug,
                  dose: next.dose,
                  amount: next.amount,
                  unit: next.unit,
                  freq: next.freq,
                  freqText: next.freqText,
                  note: next.note,
                  setting: next.setting,
                  startDate: next.startDate,
                  days: next.days,
                });
                setEditCourseId(null);
              }}
            />
          ) : (
            <div className="course" key={c.id}>
              <div className="nm">
                {c.drug}
                <small>
                  {c.dose || "dose not recorded"}
                  {SETTING_WORD[c.setting] ? " · " + SETTING_WORD[c.setting] : ""}
                </small>
                {c.note ? <small>{c.note}</small> : null}
              </div>
              {c.freq > 0 && (
                <span
                  className={
                    "pill" + (((day.courseDoses || {})[c.id] || 0) >= c.freq ? " ok" : "")
                  }
                >
                  {Math.min((day.courseDoses || {})[c.id] || 0, c.freq)} of {c.freq} today
                </span>
              )}
              <span className="pill">
                {c.days ? `day ${diffDays(c.startDate, date) + 1} of ${c.days}` : `day ${diffDays(c.startDate, date) + 1}`}
              </span>
              <div className="rowacts">
                <button className="btn sm" onClick={() => endCourse(c.id, date)}>
                  End
                </button>
                <button
                  className="iconsm"
                  aria-label={"Edit " + c.drug}
                  onClick={() => setEditCourseId(c.id)}
                >
                  {"✎"}
                </button>
                <button
                  className="iconsm del"
                  aria-label={"Delete " + c.drug}
                  onClick={() => {
                    if (window.confirm("Delete " + c.drug + " from your record? Ending a course keeps it in your history; deleting removes it.")) {
                      deleteCourse(c.id);
                    }
                  }}
                >
                  {"×"}
                </button>
              </div>
            </div>
          )
        )}
        {finishedCourses.map((c) => (
          <div key={c.id} style={{ paddingTop: 14 }}>
            <div className="course" style={{ paddingBottom: 4 }}>
              <div className="nm">
                {c.drug}
                <small>finished {fmtShortYr(addDays(c.startDate, c.days - 1))}</small>
              </div>
              <span className="pill done">review</span>
              <div className="rowacts">
                <button
                  className="iconsm"
                  aria-label={"Edit " + c.drug}
                  onClick={() => setEditCourseId(c.id)}
                >
                  {"✎"}
                </button>
                <button
                  className="iconsm del"
                  aria-label={"Delete " + c.drug}
                  onClick={() => {
                    if (window.confirm("Delete " + c.drug + " from your record? This removes it from your history for good.")) {
                      deleteCourse(c.id);
                    }
                  }}
                >
                  {"×"}
                </button>
              </div>
            </div>
            <ResponseProfile resp={courseResponse(c, state.days)} />
            {(() => {
              const a = courseAdherence(c, state.days);
              if (!a) return null;
              return (
                <div className="note" style={{ marginTop: 10 }}>
                  You ticked off {a.taken} of {a.expected} doses
                  {a.taken < a.expected
                    ? ". Worth mentioning if it did not work as expected."
                    : ". A full course."}
                </div>
              );
            })()}
            <div className="note" style={{ margin: "13px 0 7px" }}>
              That is what the log shows. How did it feel?
            </div>
            <Seg options={OUTCOMES} value={c.outcome || null} onChange={(v) => setCourseOutcome(c.id, v)} small />
            <input
              className="inp"
              style={{ marginTop: 8 }}
              placeholder="Side effects, anything worth remembering"
              value={c.outcomeNote || ""}
              onChange={(e) => setCourseNote(c.id, e.target.value)}
            />
          </div>
        ))}
      </div>
    </>
  );

  const hasTags = (day.tags || []).length > 0;
  const tagSection = (
    <div className="card">
      <div className="card-t">
        <span>Tags</span>
        {!showTags && !hasTags && (
          <button className="btn sm" onClick={() => setShowTags(true)}>
            Add
          </button>
        )}
      </div>
      {showTags || hasTags ? (
        <TagPicker
          selected={day.tags || []}
          all={state.tags || []}
          onToggle={upTag}
          onCreate={(t) => {
            addTag(t);
            upTag(t);
          }}
          onDelete={deleteTag}
        />
      ) : (
        <div className="note">Exposure, context, anything you will want to find later.</div>
      )}
    </div>
  );

  const noteSection = (
    <div className="card">
      <div className="card-t">
        <span>Notes</span>
        {!showNote && !day.notes && !day.extraSupps && (
          <button className="btn sm" onClick={() => setShowNote(true)}>
            Add
          </button>
        )}
      </div>
      {showNote || day.notes || day.extraSupps ? (
        <>
          <textarea
            className="inp"
            placeholder="What helped, what the doctor said, how the night went."
            value={day.notes}
            onChange={(e) => up({ notes: e.target.value })}
          />
          <input
            className="inp"
            style={{ marginTop: 8 }}
            placeholder="Other supplements today"
            value={day.extraSupps}
            onChange={(e) => up({ extraSupps: e.target.value })}
          />
        </>
      ) : (
        <div className="note">Nothing written for this day.</div>
      )}
    </div>
  );

  /* ---------------- render ---------------- */

  return (
    <>
      {showOnsetPrompt && (
        <div className="nudge">
          <div style={{ marginBottom: 12, fontWeight: 500, color: "var(--ink)" }}>
            When did this actually start?
          </div>
          <div className="chips" style={{ marginBottom: 10 }}>
            {[1, 2, 3, 7].map((n) => (
              <button
                key={n}
                className={"chip" + (onsetPick === addDays(date, -n) ? " on" : "")}
                onClick={() => setOnsetDate(addDays(date, -n))}
              >
                {n === 1 ? "Yesterday" : n + " days ago"}
              </button>
            ))}
          </div>
          <div className="locrow" style={{ marginTop: 0 }}>
            <input
              className="inp"
              type="date"
              value={onsetPick}
              max={addDays(date, -1)}
              min={addDays(date, -120)}
              onChange={(e) => setOnsetDate(e.target.value)}
            />
            <button
              className="btn pri"
              onClick={() => {
                const span = diffDays(onsetPick, date);
                for (let i = 1; i <= span; i++) setStatus(addDays(date, -i), "unwell");
                up({ onsetChecked: true });
              }}
            >
              Set
            </button>
          </div>
          <div className="note" style={{ marginTop: 9 }}>
            That makes today day {diffDays(onsetPick, date) + 1} of this episode. Those days are marked unwell with
            no detail, so you can fill any of them in later from the month view.
          </div>
          <button className="btn sm" style={{ marginTop: 12 }} onClick={() => up({ onsetChecked: true })}>
            It started today
          </button>
        </div>
      )}

      {date === todayISO() && day.peakFlow !== "" && (
        <div className="card">
          <div className="card-t"><span>Peak flow</span></div>
          <PeakFlowInsight days={state.days} date={date} value={day.peakFlow} />
        </div>
      )}

      {apptSoon && (state.noted || {})["appt"] !== state.appt.date && (
        <div className="remind">
          <span className="txt">
            {state.appt.who ? state.appt.who : "Appointment"}{" "}
            {apptDays === 0 ? "today" : apptDays === 1 ? "tomorrow" : `in ${apptDays} days`}
            <small>
              {openQuestions ? `${openQuestions} thing${openQuestions === 1 ? "" : "s"} on your list` : "nothing on your list yet"}
            </small>
          </span>
          <button className="btn sm" onClick={() => setTab("report")}>Open</button>
          {/* keyed to the appointment date, so closing this one does not silence
              the next appointment you book */}
          <button className="remx" onClick={() => onNote("appt", state.appt.date)} aria-label="Dismiss">
            {"×"}
          </button>
        </div>
      )}

      {pfDue && tracks("peakFlow") && (
        <PeakFlowReminder
          lastPF={lastPF}
          date={date}
          onSave={(v) => up({ peakFlow: v })}
          onDismiss={() => up({ pfSnoozed: true })}
        />
      )}

      <EarlyWarning
        days={state.days}
        regimen={state.regimen}
        seen={state.ewSeen}
        onDismiss={onDismissWarning}
      />

      {isUnwell && (state.rescue || []).length > 0 && (
        <RescuePack
          pack={state.rescue}
          onChange={setRescue}
          onStartCourse={(r) => {
            addCourse({
              id: "c" + Date.now(),
              drug: r.name,
              dose: r.dose,
              startDate: date,
              days: null,
            });
            setRescue((state.rescue || []).map((x) => (x.id === r.id ? { ...x, lastUsed: date } : x)));
            setShowDetail(true);
          }}
        />
      )}

      {isUnwell ? (
        <>
          {careSection}
          {sputumSection}
          {symptomSection}
          {detailSection}
          {tracks("culture") && cultureSection}
          {tracks("aqi") && airSection}
          {tagSection}
          {noteSection}
          <EpisodeHandover episodes={episodes} days={state.days} regimen={state.regimen} />
        </>
      ) : (
        <>
          {careSection}
          {sputumSection}
          {tracks("aqi") && airSection}
          {tagSection}
          {showDetail ? (
            detailSection
          ) : (
            <button className="btn wide" style={{ marginTop: 20 }} onClick={() => setShowDetail(true)}>
              Add measurements or a medication course
            </button>
          )}
          {noteSection}
        </>
      )}

      {/* The foot of the page is the last thing seen before the app is closed, so it
          reports what is still outstanding rather than confirming you arrived. Feeling
          well is exactly when the nebuliser gets forgotten. */}
      <div className={"savednote no-print" + (careLeft.length ? " todo" : "")}>
        <div className="tick">{careLeft.length ? "○" : "✓"}</div>
        <div className="tx">
          {careLeft.length ? (
            <>
              <b>Still to do today</b>
              {careLeft.map((r) => r.name + (r.left > 1 ? " ×" + r.left : "")).join(", ")}
            </>
          ) : todayPlan.length ? (
            <>
              <b>Your care is done for today</b>
              {logged ? "This day is saved on your device." : "Entries save as you type."}
            </>
          ) : (
            <>
              <b>{logged ? "Saved" : "Nothing logged yet"}</b>
              {logged ? "This day is stored on your device." : "Entries save as you type."}
            </>
          )}
        </div>
        {careLeft.length > 0 && (
          <button
            className="btn sm"
            onClick={() => {
              const el = [...document.querySelectorAll(".card")].find((c) => /Today's care/.test(c.textContent));
              if (el) el.scrollIntoView({ block: "start", behavior: "smooth" });
            }}
          >
            Go
          </button>
        )}
      </div>

      {logged && (
        <button className="btn wide" style={{ marginTop: 14, color: "var(--faint)" }} onClick={() => clearDay(date)}>
          Erase this day
        </button>
      )}
    </>
  );
}

// Doubles as the editor for a course already recorded. Passing `course` fills the
// fields from it and turns the button into a save, so a name typed wrong is a
// correction rather than something to delete and re-enter.
function CourseForm({ date, onAdd, customDrugs, onRemember, onForgetDrug, course, onCancel }) {
  const LIST = [...DRUGS.filter((d) => d.name !== "Other"), ...customDrugs, { name: "Other", dose: "", days: 7 }];
  const known = course ? LIST.findIndex((d) => d.name === course.drug) : -1;
  const [drugIdx, setDrugIdx] = useState(course ? (known >= 0 ? known : LIST.length - 1) : 0);
  const [custom, setCustom] = useState(course && known < 0 ? course.drug : "");
  const seed = course && course.amount != null ? course : parseDose(course ? course.dose : DRUGS[0].dose);
  const [amount, setAmount] = useState(seed.amount || "");
  const [unit, setUnit] = useState(seed.unit || "mg");
  const [freq, setFreq] = useState(seed.freq || 0);
  const [freqText, setFreqText] = useState(seed.freqText || "");
  const [note, setNote] = useState((course && course.note) || "");
  const [setting, setSetting] = useState((course && course.setting) || "home");
  const [days, setDays] = useState(course ? (course.days == null ? "" : course.days) : DRUGS[0].days);
  const [start, setStart] = useState(course ? course.startDate : date);
  const [tidy, setTidy] = useState(false);

  const pick = (i) => {
    setDrugIdx(i);
    const p = parseDose(LIST[i].dose);
    setAmount(p.amount);
    setUnit(p.unit || "mg");
    setFreq(p.freq);
    setFreqText(p.freqText);
    setDays(LIST[i].days);
  };
  const isOther = LIST[drugIdx].name === "Other";
  const preview = doseText({ amount, unit, freq, freqText });

  return (
    <div className="card flat" style={{ marginTop: 0, marginBottom: 12 }}>
      <select className="inp" value={drugIdx} onChange={(e) => pick(Number(e.target.value))}>
        {LIST.map((d, i) => (
          <option key={d.name + i} value={i}>
            {d.name}
          </option>
        ))}
      </select>
      {isOther && (
        <input
          className="inp"
          style={{ marginTop: 8 }}
          placeholder="Medication name"
          value={custom}
          onChange={(e) => setCustom(e.target.value)}
        />
      )}
      <div className="rowlab">Dose</div>
      <div style={{ display: "flex", gap: 8 }}>
        <input
          className="inp"
          style={{ flex: 1 }}
          type="number"
          inputMode="decimal"
          step="any"
          placeholder="500"
          value={amount}
          onChange={(e) => setAmount(e.target.value)}
        />
        <select className="inp" style={{ width: 128 }} value={unit} onChange={(e) => setUnit(e.target.value)}>
          {DOSE_UNITS.map((u) => (
            <option key={u} value={u}>
              {u}
            </option>
          ))}
        </select>
      </div>

      <div className="rowlab">How often</div>
      <select className="inp" value={freq} onChange={(e) => setFreq(Number(e.target.value))}>
        {FREQS.map((f) => (
          <option key={f.v} value={f.v}>
            {f.label}
          </option>
        ))}
      </select>
      {freq === 0 && (
        <input
          className="inp"
          style={{ marginTop: 8 }}
          placeholder="every 6 to 8 hours, alternate days"
          value={freqText}
          onChange={(e) => setFreqText(e.target.value)}
        />
      )}

      <div className="rowlab">Where</div>
      <Seg options={SETTINGS} value={setting} onChange={(v) => setSetting(v || "home")} small />

      <div className="rowlab">Anything special about how you take it</div>
      <input
        className="inp"
        placeholder="2 tablets on day 1, then 1 a day. With food."
        value={note}
        onChange={(e) => setNote(e.target.value)}
      />

      <div style={{ display: "flex", gap: 8, marginTop: 8 }}>
        <div style={{ flex: 1 }}>
          <div className="rowlab" style={{ marginTop: 0 }}>Start</div>
          <input className="inp" type="date" value={start} onChange={(e) => setStart(e.target.value)} />
        </div>
        <div style={{ width: 110 }}>
          <div className="rowlab" style={{ marginTop: 0 }}>Days</div>
          <input
            className="inp"
            type="number"
            inputMode="numeric"
            value={days}
            onChange={(e) => setDays(e.target.value)}
          />
        </div>
      </div>
      <div style={{ display: "flex", gap: 8, marginTop: 10 }}>
        {onCancel && (
          <button className="btn" style={{ flex: "0 0 auto" }} onClick={onCancel}>
            Cancel
          </button>
        )}
        <button
          className="btn pri wide"
          style={{ flex: 1, width: "auto" }}
          onClick={() => {
            const name = isOther ? custom.trim() || "Unnamed medication" : LIST[drugIdx].name;
            const fields = { amount: String(amount).trim(), unit, freq, freqText: freqText.trim() };
            // `dose` stays the single string every reader prints, rebuilt from the
            // pickers so the record reads the same way it always has
            const dose = doseText(fields);
            if (isOther && custom.trim()) {
              onRemember({ name: custom.trim(), dose, days: days === "" ? 7 : Number(days) });
            }
            onAdd({
              id: course ? course.id : "c" + Date.now(),
              drug: name,
              dose,
              ...fields,
              note: note.trim(),
              setting,
              startDate: start,
              days: days === "" ? null : Number(days),
            });
          }}
        >
          {course ? "Save changes" : "Add course"}
        </button>
      </div>

      {customDrugs.length > 0 && onForgetDrug && (
        <>
          <button
            className="chip add"
            style={{ marginTop: 12 }}
            onClick={() => setTidy((v) => !v)}
          >
            {tidy ? "Done" : "Edit saved medications"}
          </button>
          {tidy && (
            <>
              <div className="chips" style={{ marginTop: 10 }}>
                {customDrugs.map((d) => (
                  <button
                    key={d.name}
                    className="chip"
                    onClick={() => {
                      onForgetDrug(d.name);
                      if (LIST[drugIdx] && LIST[drugIdx].name === d.name) pick(0);
                    }}
                  >
                    {d.name}
                    {"  ×"}
                  </button>
                ))}
              </div>
              <div className="note" style={{ marginTop: 10 }}>
                Tap one to drop it from this list. Courses already recorded with that name
                are untouched.
              </div>
            </>
          )}
        </>
      )}
    </div>
  );
}

