// Compares airway-care adherence in the run-up to episodes against settled well stretches.
// Association only, and it says so.
function YearOnYear({ episodes }) {
  const today = todayISO();
  const y1 = addDays(today, -365);
  const y2 = addDays(today, -730);
  const recent = episodes.filter((e) => e.start >= y1).length;
  const prior = episodes.filter((e) => e.start >= y2 && e.start < y1).length;
  const priorSpan = episodes.length && episodes[0].start < y1;
  if (!episodes.length) return null;
  const diff = prior - recent;
  return (
    <div className="card">
      <div className="card-t"><span>Episodes a year</span></div>
      <div className="stats" style={{ gridTemplateColumns: priorSpan ? "1fr 1fr" : "1fr" }}>
        <div className="stat">
          <div className="v">{recent}</div>
          <div className="k">last 12 months</div>
        </div>
        {priorSpan && (
          <div className="stat">
            <div className="v">{prior}</div>
            <div className="k">the 12 before</div>
          </div>
        )}
      </div>
      <div className="note" style={{ marginTop: 12 }}>
        {!priorSpan
          ? "One more year of logging and this becomes a comparison rather than a count."
          : diff > 0
          ? `${diff} fewer than the year before. That is the number this whole log exists to move.`
          : diff < 0
          ? `${Math.abs(diff)} more than the year before. Worth raising at your next appointment with the episode table in hand.`
          : "The same as the year before."}
      </div>
    </div>
  );
}

function CarePayoff({ days, episodes, regimen }) {
  const stat = useMemo(() => {
    if (episodes.length < 2) return null;
    const preKeys = new Set();
    const epKeys = new Set();
    episodes.forEach((e) => {
      for (let i = 1; i <= 30; i++) preKeys.add(addDays(e.start, -i));
      spanDates(e).forEach((d) => epKeys.add(d));
    });
    const rate = (keys) => {
      let n = 0, hit = 0;
      keys.forEach((k) => {
        const day = days[k];
        if (!day || !day.status) return;
        n++;
        if (careComplete(day, regimen)) hit++;
      });
      return n >= 10 ? { pct: Math.round((hit / n) * 100), n } : null;
    };
    const settled = Object.keys(days).filter((k) => !preKeys.has(k) && !epKeys.has(k));
    const pre = rate([...preKeys]);
    const calm = rate(settled);
    if (!pre || !calm) return null;
    return { pre, calm };
  }, [days, episodes]);

  if (!stat) return null;
  const gap = stat.calm.pct - stat.pre.pct;
  return (
    <div className="card">
      <div className="card-t"><span>Care and what follows</span></div>
      <div className="stats" style={{ gridTemplateColumns: "1fr 1fr" }}>
        <div className="stat">
          <div className="v">{stat.calm.pct}<small>%</small></div>
          <div className="k">settled stretches</div>
        </div>
        <div className="stat">
          <div className="v">{stat.pre.pct}<small>%</small></div>
          <div className="k">month before an episode</div>
        </div>
      </div>
      <div className="note" style={{ marginTop: 12 }}>
        {gap >= 10
          ? `Your saline and Aerobika rate ran ${gap} points lower in the month before an episode than during settled stretches. That is an association across ${episodes.length} episodes, not proof of cause, and illness itself disrupts routines. Still worth knowing.`
          : gap <= -10
          ? `Your care rate was actually higher in the month before an episode, which usually means you were already ramping up as you felt something coming.`
          : `Care rates look much the same either side, so nothing to read into yet.`}
      </div>
    </div>
  );
}

function AirPayoff({ days, episodes }) {
  const stat = useMemo(() => {
    if (episodes.length < 2) return null;
    const preKeys = new Set();
    const epKeys = new Set();
    episodes.forEach((e) => {
      for (let i = 1; i <= 7; i++) preKeys.add(addDays(e.start, -i));
      spanDates(e).forEach((d) => epKeys.add(d));
    });
    const mean = (keys) => {
      const vals = keys
        .map((k) => days[k])
        .filter((d) => d && d.aqi && d.aqi.value != null)
        .map((d) => d.aqi.value);
      return vals.length >= 5
        ? { v: Math.round(vals.reduce((a, b) => a + b, 0) / vals.length), n: vals.length }
        : null;
    };
    const settled = Object.keys(days).filter((k) => !preKeys.has(k) && !epKeys.has(k));
    const pre = mean([...preKeys]);
    const calm = mean(settled);
    if (!pre || !calm) return null;
    return { pre, calm };
  }, [days, episodes]);

  if (!stat) return null;
  const gap = stat.pre.v - stat.calm.v;
  return (
    <div className="card">
      <div className="card-t"><span>Air and what follows</span></div>
      <div className="stats" style={{ gridTemplateColumns: "1fr 1fr" }}>
        <div className="stat">
          <div className="v" style={{ color: aqiBand(stat.calm.v).hex }}>{stat.calm.v}</div>
          <div className="k">settled stretches</div>
        </div>
        <div className="stat">
          <div className="v" style={{ color: aqiBand(stat.pre.v).hex }}>{stat.pre.v}</div>
          <div className="k">week before an episode</div>
        </div>
      </div>
      <div className="note" style={{ marginTop: 12 }}>
        {gap >= 15
          ? `Air quality ran ${gap} AQI points worse in the week before an episode than during settled stretches, across ${episodes.length} episodes. Bad air and viral season overlap in Bangkok, so this cannot separate the two. It is a reason to be stricter with clearance on smoky weeks, not a cause.`
          : gap <= -15
          ? `Air was actually cleaner in the week before your episodes, which points at infection rather than pollution as the trigger.`
          : `Air quality looks much the same either side, so nothing to read into yet.`}
      </div>
    </div>
  );
}

function TrendsView({ state, episodes }) {
  const days = state.days;
  const keys = Object.keys(days).sort();
  const today = todayISO();

  const window30 = useMemo(() => {
    const arr = [];
    for (let i = 29; i >= 0; i--) arr.push(addDays(today, -i));
    return arr;
  }, [today]);

  const adherence = useMemo(() => {
    const tally = {};
    let logged = 0;
    window30.forEach((d) => {
      const day = days[d];
      if (!day || !day.status) return;
      logged++;
      planOf(day, state.regimen).forEach((r) => {
        if (!tally[r.id]) tally[r.id] = { id: r.id, name: r.name, done: 0, target: 0 };
        tally[r.id].done += Math.min(day.care[r.id] || 0, r.target);
        tally[r.id].target += r.target;
      });
    });
    const rows = Object.values(tally);
    const target = rows.reduce((n, r) => n + r.target, 0);
    const done = rows.reduce((n, r) => n + r.done, 0);
    return { rows, logged, pct: target ? Math.round((done / target) * 100) : 0 };
  }, [days, window30, state.regimen]);

  const pfData = useMemo(
    () =>
      keys
        .filter((k) => days[k].peakFlow !== "" && !isNaN(parseFloat(days[k].peakFlow)))
        .map((k) => ({ date: fmtShort(k), raw: k, pf: parseFloat(days[k].peakFlow) })),
    [keys, days]
  );

  const gaps = gapsBetween(episodes);
  const gapData = episodes.slice(1).map((e, i) => ({
    label: fmtShort(e.start),
    gap: gaps[i],
  }));

  const symptomData = useMemo(() => {
    const last = episodes[episodes.length - 1];
    if (!last) return [];
    return spanDates(last).map((d) => {
      const day = days[d];
      return {
        label: "d" + (diffDays(last.start, d) + 1),
        burden:
          day && day.symptomsReviewed !== false
            ? Object.values(day.symptoms).reduce((a, b) => a + b, 0)
            : null,
      };
    });
  }, [episodes, days]);

  const logRate = useMemo(() => {
    let n = 0;
    window30.forEach((d) => {
      if (days[d] && days[d].status) n++;
    });
    return n;
  }, [days, window30]);

  if (keys.length === 0) {
    return (
      <div className="empty">
        <strong>Nothing logged yet</strong>
        Log a few days and the trends will fill in here. Charts only draw real entries, so gaps stay gaps.
      </div>
    );
  }

  return (
    <>
      <div className="card">
        <div className="card-t"><span>Last 30 days</span></div>
        <div className="stats" style={{ gridTemplateColumns: "1fr 1fr" }}>
          <div className="stat">
            <div className="v">{logRate}<small>/30</small></div>
            <div className="k">days logged</div>
          </div>
          <div className="stat">
            <div className="v">{adherence.pct}<small>%</small></div>
            <div className="k">doses taken</div>
          </div>
        </div>
        {adherence.rows.map((r) => (
          <div className="resp-row" key={r.id || r.name}>
            <span className="nm">{r.name}</span>
            <span className="val">{r.target ? Math.round((r.done / r.target) * 100) : 0}%</span>
          </div>
        ))}
        <div className="note" style={{ marginTop: 12 }}>
          Counted over the {adherence.logged} days you logged.
        </div>
      </div>

      <YearOnYear episodes={episodes} />

      <CarePayoff days={days} episodes={episodes} regimen={state.regimen} />

      <AirPayoff days={days} episodes={episodes} />

      <div className="card">
        <div className="card-t"><span>Peak flow</span><span className="hint">best of three</span></div>
        {pfData.length < 2 ? (
          <div className="note">Two readings needed before this draws. Weekly is enough when you're well; daily during an episode.</div>
        ) : (
          <MiniChart data={pfData.map((d) => ({ label: d.date, value: d.pf }))} />
        )}
      </div>

      <div className="card">
        <div className="card-t"><span>Days between episodes</span></div>
        {gapData.length < 2 ? (
          <div className="note">
            You need at least three recorded episodes before a gap pattern means anything, and realistically about
            twelve months before you can call a direction. Year one is collection.
          </div>
        ) : (
          <>
            <MiniChart kind="bar" data={gapData.map((d) => ({ label: d.label, value: d.gap }))} />
            <div className="note" style={{ marginTop: 8 }}>
              Median gap {median(gaps)} days across {gaps.length} intervals. Each bar is the well stretch before that
              episode started.
            </div>
          </>
        )}
      </div>

      {symptomData.length > 1 && (
        <div className="card">
          <div className="card-t">
            <span className="ttl">
              Most recent episode
              <Info title="Symptom burden">
                <p>Each bar is that day's symptom scores added together.</p>
                <p>
                  It is only comparable inside one episode. Which symptoms you track, and how you rate them, drift
                  over time, so comparing one year's bars against another's would not mean much.
                </p>
              </Info>
            </span>
            <span className="hint">symptom burden by day</span>
          </div>
          <MiniChart kind="bar" height={150} color="#2FA5DC" data={symptomData.map((d) => ({ label: d.label, value: d.burden }))} />

        </div>
      )}
    </>
  );
}

/* ------------------------------------------------------------------ */
/*  Episodes view                                                      */
/* ------------------------------------------------------------------ */

function EpisodeCard({ ep, days, prevEnd, onOpen }) {
  return (
    <div className="ep">
     <div className="ep-in">
      <div className="ep-h">
        <div className="ep-d">
          {fmtShortYr(ep.start)} → {fmtShortYr(ep.end)}
          <small style={{ display: "block" }}>
            {ep.span} days{prevEnd ? ` · ${diffDays(prevEnd, ep.start)} well days before` : ""}
          </small>
        </div>
        {onOpen && (
          <button className="btn sm" onClick={() => onOpen(ep)}>
            Open
          </button>
        )}
      </div>
      <div className="ep-strip">
        {spanDates(ep).map((d) => {
          const day = days[d];
          if (!day) {
            return <div key={d} className="c" title={`${fmtShort(d)} · not logged`} style={{ background: "#D2DCE6", height: "6%" }} />;
          }
          const c = day.sputum.color;
          const v = day.sputum.volume;
          return (
            <div
              key={d}
              className="c"
              title={`${fmtShort(d)}${c != null ? " · " + SPUTUM[c].label.replace("\n", " ") : ""}`}
              style={{
                background: c != null ? SPUTUM[c].hex : "#C9D4DB",
                height: (v == null ? 55 : 12 + (v / SCALE_MAX) * 88) + "%",
              }}
            />
          );
        })}
      </div>
      <div className="ep-meta">
        {ep.peakColor != null && (
          <span className="tag">peak {SPUTUM[ep.peakColor].label.replace("\n", " ").toLowerCase()}</span>
        )}
        {ep.blood && <span className="tag blood">haemoptysis</span>}
        {(ep.organisms || []).map((o) => (
          <span className="tag" key={o}>culture: {o}</span>
        ))}
        {ep.maxTemp != null && <span className="tag">max {ep.maxTemp}°C</span>}
        {ep.meanAqi != null && <span className="tag">AQI {ep.meanAqi} avg</span>}
        {ep.minPeakFlow != null && <span className="tag">low PF {ep.minPeakFlow}</span>}
        {ep.meds.map((m) => (
          <span className="tag" key={m.id}>
            {m.drug}
            {m.outcome ? " \u00b7 " + (OUTCOMES.find((o) => o.v === m.outcome) || {}).label.toLowerCase() : ""}
          </span>
        ))}
        {ep.triggers.map((t) => (
          <span className="tag" key={t}>
            {t}
          </span>
        ))}
        {ep.loggedDays < ep.span && (
          <span className="tag">{ep.loggedDays} of {ep.span} days logged</span>
        )}
      </div>
     </div>
    </div>
  );
}

function EpisodesView({ state, episodes, setDate, setTab }) {
  const [open, setOpen] = useState(null);
  const days = state.days;

  if (!episodes.length) {
    return (
      <div className="empty">
        <strong>No episodes recorded</strong>
        An episode forms automatically the moment you mark a day unwell, and closes after a week without one. Nothing
        to set up.
      </div>
    );
  }

  const list = [...episodes].reverse();
  const durations = episodes.map((e) => e.span);
  const gaps = gapsBetween(episodes);

  if (open) {
    return (
      <>
        <button className="btn" style={{ marginTop: 14 }} onClick={() => setOpen(null)}>
          &#8249; All episodes
        </button>
        <div className="card">
          <div className="card-t">
            <span>Episode {open.index} · {fmtShortYr(open.start)}</span>
          </div>
          <div className="scrollx">
            <DayTable dates={spanDates(open)} days={days} />
          </div>
          <div className="handover" style={{ marginTop: 14 }}>
            {episodeSummary(open, days, state.regimen)}
          </div>
          <div className="btnrow" style={{ marginTop: 12 }}>
            <button className="btn pri" onClick={() => copyText(episodeSummary(open, days, state.regimen))}>
              Copy write-up
            </button>
            <button
              className="btn"
              onClick={() => {
                setDate(open.start);
                setTab("today");
              }}
            >
              Edit from day one
            </button>
          </div>
        </div>
        {spanDates(open).some((d) => days[d] && days[d].notes) && (
          <div className="card">
            <div className="card-t"><span>Notes</span></div>
            {spanDates(open)
              .filter((d) => days[d] && days[d].notes)
              .map((d) => (
                <div key={d} style={{ marginBottom: 10 }}>
                  <div style={{ fontFamily: "var(--mono)", fontSize: 10.5, color: "var(--muted)", letterSpacing: ".05em" }}>
                    {fmtShort(d).toUpperCase()}
                  </div>
                  <div style={{ fontSize: 13.5 }}>{days[d].notes}</div>
                </div>
              ))}
          </div>
        )}
      </>
    );
  }

  return (
    <>
      <div className="card">
        <div className="card-t"><span>All time</span></div>
        <div className="stats">
          <div className="stat">
            <div className="v">{episodes.length}</div>
            <div className="k">episodes</div>
          </div>
          <div className="stat">
            <div className="v">{median(durations)}<small> d</small></div>
            <div className="k">median length</div>
          </div>
          <div className="stat">
            <div className="v">{gaps.length ? median(gaps) : "—"}<small>{gaps.length ? " d" : ""}</small></div>
            <div className="k">median gap</div>
          </div>
        </div>
      </div>
      {list.map((ep, i) => {
        const prev = list[i + 1];
        return <EpisodeCard key={ep.id} ep={ep} days={days} prevEnd={prev ? prev.end : null} onOpen={setOpen} />;
      })}
    </>
  );
}

function DayTable({ dates, days }) {
  return (
    <table className="tbl">
      <thead>
        <tr>
          <th>Date</th>
          <th>Sputum</th>
          <th>Vol</th>
          <th>Blood</th>
          <th>Top symptoms</th>
          <th>Temp</th>
          <th>SpO&#8322;</th>
          <th>PF</th>
          <th>Care</th>
        </tr>
      </thead>
      <tbody>
        {dates.map((d) => {
          const day = days[d];
          if (!day) {
            return (
              <tr key={d}>
                <td className="m">{fmtShort(d)}</td>
                <td className="m" colSpan={8} style={{ color: "var(--muted)" }}>
                  not logged
                </td>
              </tr>
            );
          }
          const top =
            day.symptomsReviewed === false
              ? "not reviewed"
              : Object.entries(day.symptoms)
                  .filter(([, v]) => v > 0)
                  .sort((a, b) => b[1] - a[1])
                  .slice(0, 3)
                  .map(([k, v]) => `${symLabel(k)} ${SEV[v].toLowerCase()}`)
                  .join(", ");
          const care = [
            ...planOf(day, null).map((r) =>
              day.care[r.id] ? r.name.split(" ")[0] + " " + Math.min(day.care[r.id], r.target) + "/" + r.target : null
            ),
            ...Object.entries(day.prn || {})
              .filter(([, n]) => n > 0)
              .map(([m, n]) => m.split(" ")[0] + "\u00d7" + n),
          ]
            .filter(Boolean)
            .join(" ");
          return (
            <tr key={d}>
              <td className="m">{fmtShort(d)}</td>
              <td className="m">
                {day.sputum.color != null ? (
                  <span style={{ display: "inline-flex", alignItems: "center", gap: 5 }}>
                    <span
                      style={{
                        width: 10,
                        height: 10,
                        borderRadius: 3,
                        background: SPUTUM[day.sputum.color].hex,
                        border: "1px solid rgba(0,0,0,.15)",
                        display: "inline-block",
                      }}
                    />
                    {SPUTUM[day.sputum.color].label.replace("\n", " ")}
                  </span>
                ) : (
                  "—"
                )}
              </td>
              <td className="m">{day.sputum.volume != null ? VOLUME[day.sputum.volume] : "—"}</td>
              <td className="m" style={{ color: day.blood && day.blood !== "none" ? "var(--alarm)" : undefined }}>
                {day.blood ? BLOOD.find((b) => b.v === day.blood).label : "—"}
              </td>
              <td>{top || "—"}</td>
              <td className="m">{day.temp || "—"}</td>
              <td className="m">{day.spo2 || "—"}</td>
              <td className="m">{day.peakFlow || "—"}</td>
              <td className="m">{care || "—"}</td>
            </tr>
          );
        })}
      </tbody>
    </table>
  );
}

/* ------------------------------------------------------------------ */
/*  Report view                                                        */
/* ------------------------------------------------------------------ */

const RANGES = [
  { v: 90, label: "Last 90 days" },
  { v: 180, label: "Last 6 months" },
  { v: 365, label: "Last 12 months" },
  { v: 0, label: "Everything" },
];

function Snapshots({ onRestore }) {
  const [snaps] = useState(() => listSnapshots());
  if (!snaps.length) return null;
  return (
    <>
      <div className="rowlab">Automatic copies</div>
      <div className="note" style={{ marginBottom: 9 }}>
        One a day, kept on this device. These go when your browser data goes, so they are not a backup.
      </div>
      {snaps.map((sn) => (
        <div className="course" key={sn.key}>
          <div className="nm">
            {fmtShortYr(sn.date)}
            <small>{Math.max(1, Math.round(sn.size / 1024))} KB</small>
          </div>
          <button
            className="btn sm"
            onClick={() => {
              if (!window.confirm(`Replace everything with the copy from ${fmtShortYr(sn.date)}?`)) return;
              try {
                onRestore(migrate(JSON.parse(localStorage.getItem(sn.key))));
              } catch (e) {
                window.alert("That copy could not be read.");
              }
            }}
          >
            Restore
          </button>
        </div>
      ))}
    </>
  );
}

function StorageHealth({ days }) {
  const [info, setInfo] = useState(null);
  useEffect(() => {
    let live = true;
    requestPersistence().then((r) => live && setInfo(r));
    return () => {
      live = false;
    };
  }, []);
  const last = lastBackupAt();
  const age = last ? diffDays(last, todayISO()) : null;
  const stale = days > 0 && (last == null || age >= 30);
  return (
    <>
      <div className={"insight " + (stale ? "warn" : "")} style={{ marginTop: 0 }}>
        {last ? (
          <>
            Last backup {age === 0 ? "today" : age === 1 ? "yesterday" : age + " days ago"}.
            {stale ? " Worth doing another one." : ""}
          </>
        ) : (
          <>
            No backup taken yet. Everything lives in this browser on this device, so send one somewhere safe before
            you have a year of entries to lose.
          </>
        )}
      </div>
      {info && info.supported && (
        <div className={"insight " + (info.granted ? "good" : "warn")}>
          {info.granted
            ? "Storage is marked as persistent, so the browser will not clear it to reclaim space."
            : "The browser has not granted persistent storage. Adding this to your home screen usually earns it, and it stops your data being cleared after a stretch of not opening the app."}
          {info.usage != null ? ` Using ${Math.max(1, Math.round(info.usage / 1024))} KB.` : ""}
        </div>
      )}
      <div className="note" style={{ marginTop: 10 }}>
        Clear {BUILD}. Nothing is sent anywhere. A backup is a file you keep.
      </div>
    </>
  );
}

function ReportView({ state, episodes, onImport, onWipe, onAppt, onQuestions, onRescue, onShareWeek }) {
  const [range, setRange] = useState(365);
  const [toast, setToast] = useState("");
  const fileRef = useRef(null);
  const checkRef = useRef(null);
  const [check, setCheck] = useState(null);
  const today = todayISO();
  const from = range ? addDays(today, -range + 1) : "0000-01-01";

  const eps = episodes.filter((e) => e.end >= from);
  const dateKeys = Object.keys(state.days).filter((k) => k >= from).sort();
  const durations = eps.map((e) => e.span);
  const gaps = gapsBetween(eps);

  const activeMeds = (state.courses || []).filter((c) => {
    const ce = c.days ? addDays(c.startDate, c.days - 1) : null;
    return !ce || ce >= today;
  });

  const bloodDays = dateKeys.filter((k) => state.days[k].blood && state.days[k].blood !== "none");

  const asText = () => {
    const L = [];
    L.push("BRONCHIECTASIS LOG");
    L.push(`${fmtShortYr(dateKeys[0] || today)} to ${fmtShortYr(today)}`);
    L.push("");
    L.push(`Episodes: ${eps.length}. Median length ${median(durations) ?? "n/a"} days. Median gap ${median(gaps) ?? "n/a"} days.`);
    L.push(`Days logged in range: ${dateKeys.length}.`);
    L.push(`Haemoptysis on ${bloodDays.length} day(s).`);
    L.push("");
    eps.forEach((e) => {
      L.push(`--- ${fmtShortYr(e.start)} to ${fmtShortYr(e.end)} (${e.span} days)`);
      if (e.peakColor != null) L.push(`    peak sputum: ${SPUTUM[e.peakColor].label.replace("\n", " ")}`);
      if (e.blood) L.push("    haemoptysis present");
      if ((e.organisms || []).length) L.push("    culture: " + e.organisms.join(", "));
      if (e.maxTemp != null) L.push(`    max temp ${e.maxTemp} C`);
      if (e.minPeakFlow != null) L.push(`    lowest peak flow ${e.minPeakFlow} L/min`);
      if (e.meds.length) L.push("    meds: " + e.meds.map((m) => `${m.drug} ${m.dose}`.trim()).join("; "));
      if (e.triggers.length) L.push("    tags: " + e.triggers.join(", "));
    });
    return L.join("\n");
  };

  const copy = async () => {
    const t = asText();
    try {
      await navigator.clipboard.writeText(t);
      setToast("Copied");
    } catch (e) {
      const ta = document.createElement("textarea");
      ta.value = t;
      document.body.appendChild(ta);
      ta.select();
      try { document.execCommand("copy"); setToast("Copied"); } catch (e2) { setToast("Copy failed"); }
      document.body.removeChild(ta);
    }
    setTimeout(() => setToast(""), 1600);
  };

  const download = (name, content, type) => {
    const blob = new Blob([content], { type });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = name;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    setTimeout(() => URL.revokeObjectURL(url), 1000);
  };

  const backupName = `clear-backup-${today}.json`;
  const backupBody = () => JSON.stringify(state, null, 2);

  const exportJson = () => {
    download(backupName, backupBody(), "application/json");
    markBackedUp();
    setToast("Backup saved");
    setTimeout(() => setToast(""), 1800);
  };

  const shareJson = async () => {
    try {
      const file = new File([backupBody()], backupName, { type: "application/json" });
      if (navigator.canShare && navigator.canShare({ files: [file] })) {
        await navigator.share({ files: [file], title: "Clear backup" });
        markBackedUp();
        setToast("Shared");
      } else {
        exportJson();
        return;
      }
    } catch (e) {
      if (e && e.name === "AbortError") return;
      exportJson();
      return;
    }
    setTimeout(() => setToast(""), 1800);
  };

  const exportCsv = () => {
    const head = [
      "date","status","sputum_colour","sputum_volume","sputum_texture","blood",
      "care","peak_flow","spo2","temp","resting_hr","tags","aqi","aqi_location","sample_sent","organism","as_needed",
      ...SYMPTOMS.map((s) => s[0]),"supplements","notes",
    ];
    const rows = Object.keys(state.days).sort().map((k) => {
      const d = state.days[k];
      const q = (x) => `"${String(x ?? "").replace(/"/g, '""')}"`;
      return [
        k, d.status ?? "",
        d.sputum.color != null ? SPUTUM[d.sputum.color].label.replace("\n", " ") : "",
        d.sputum.volume != null ? VOLUME[d.sputum.volume] : "",
        d.sputum.texture != null ? TEXTURE[d.sputum.texture] : "",
        d.blood ?? "",
        q(planOf(d, null).map((r) => `${r.name} ${Math.min(d.care[r.id] || 0, r.target)}/${r.target}`).join("; ")),
        d.peakFlow, d.spo2, d.temp, d.restHr, q((d.tags || []).join("; ")),
        d.aqi && d.aqi.value != null ? d.aqi.value : "", q(d.aqi ? d.aqi.location : ""),
        d.sampleSent ? 1 : 0, q(d.organism),
        q(Object.entries(d.prn || {}).filter(([, n]) => n > 0).map(([m, n]) => `${m} x${n}`).join("; ")),
        ...SYMPTOMS.map((s) => d.symptoms[s[0]] ?? ""),
        q(d.extraSupps), q(d.notes),
      ].join(",");
    });
    download(`bronchiectasis-log-${today}.csv`, [head.join(","), ...rows].join("\n"), "text/csv");
  };

  // reads a file and reports on it without touching anything, so a backup can be
  // verified without the risk of overwriting good data to find out
  const checkFile = (e) => {
    const f = e.target.files && e.target.files[0];
    e.target.value = "";
    if (!f) return;
    const r = new FileReader();
    r.onload = () => {
      try {
        const parsed = JSON.parse(r.result);
        if (!parsed || typeof parsed !== "object" || !parsed.days) throw new Error("shape");
        const keys = Object.keys(parsed.days).sort();
        const eps = buildEpisodes(migrate(JSON.parse(JSON.stringify(parsed))).days, parsed.courses || []);
        setCheck({
          cls: "good",
          text: keys.length
            ? `That file is readable. ${keys.length} days from ${fmtShortYr(keys[0])} to ${fmtShortYr(
                keys[keys.length - 1]
              )}, ${eps.length} episode${eps.length === 1 ? "" : "s"}. Nothing has been changed.`
            : "That file is readable but has no entries in it yet.",
        });
      } catch (err) {
        setCheck({ cls: "bad", text: "That file could not be read as a Clear backup. Try a different one." });
      }
      setTimeout(() => setCheck(null), 12000);
    };
    r.readAsText(f);
  };

  const importJson = (e) => {
    const f = e.target.files && e.target.files[0];
    if (!f) return;
    const r = new FileReader();
    r.onload = () => {
      try {
        const parsed = JSON.parse(r.result);
        if (!parsed || typeof parsed !== "object" || !parsed.days) throw new Error("bad");
        onImport(migrate(parsed));
        setToast("Restored");
      } catch (err) {
        setToast("That file isn't a log backup");
      }
      setTimeout(() => setToast(""), 2200);
    };
    r.readAsText(f);
    e.target.value = "";
  };

  return (
    <>
      {toast && <div className="saved">{toast}</div>}

      <div className="sectionhead no-print">Your appointment</div>
      <div className="no-print">
        <Appointment
          appt={state.appt || { date: "", who: "" }}
          questions={state.questions || []}
          onAppt={onAppt}
          onQuestions={onQuestions}
        />
      </div>

      <div className="sectionhead no-print">What you hand over</div>
      <div className="card no-print">
        <div className="card-t"><span>Report</span></div>
        <select className="inp" value={range} onChange={(e) => setRange(Number(e.target.value))}>
          {RANGES.map((r) => (
            <option key={r.v} value={r.v}>{r.label}</option>
          ))}
        </select>
        <div className="btnrow" style={{ marginTop: 10 }}>
          <button className="btn pri" onClick={() => window.print()}>Print or save as PDF</button>
          <button className="btn" onClick={copy}>Copy as text</button>
        </div>
        <div className="note" style={{ marginTop: 9 }}>
          On a phone, use <strong>Copy as text</strong> if the print dialog does not appear.
        </div>
      </div>

      <div className="print-head" style={{ marginBottom: 8 }}>
        <div style={{ fontSize: "13pt", fontWeight: 700 }}>Bronchiectasis log</div>
        <div style={{ fontSize: "9pt", color: "#555" }}>
          {dateKeys.length ? `${fmtShortYr(dateKeys[0])} to ${fmtShortYr(today)}` : "No entries"} · generated {fmtShortYr(today)}
        </div>
      </div>

      <div className="card">
        <div className="card-t"><span>Summary</span></div>
        {dateKeys.length === 0 ? (
          <div className="note">No entries in this range.</div>
        ) : (
          <>
            <div className="stats">
              <div className="stat">
                <div className="v">{eps.length}</div>
                <div className="k">episodes</div>
              </div>
              <div className="stat">
                <div className="v">{median(durations) ?? "—"}<small>{durations.length ? " d" : ""}</small></div>
                <div className="k">median length</div>
              </div>
              <div className="stat">
                <div className="v">{gaps.length ? median(gaps) : "—"}<small>{gaps.length ? " d" : ""}</small></div>
                <div className="k">median gap</div>
              </div>
              <div className="stat">
                <div className="v">{bloodDays.length}</div>
                <div className="k">haemoptysis days</div>
              </div>
              <div className="stat">
                <div className="v">{dateKeys.length}</div>
                <div className="k">days logged</div>
              </div>
              <div className="stat">
                <div className="v">{(state.courses || []).filter((c) => c.startDate >= from).length}</div>
                <div className="k">med courses</div>
              </div>
            </div>
            <div className="note" style={{ marginTop: 10 }}>
              Logged days only.
            </div>
          </>
        )}
      </div>

      {(state.questions || []).some((q) => !q.done) && (
        <div className="card">
          <div className="card-t"><span>To raise at this appointment</span></div>
          {(state.questions || [])
            .filter((q) => !q.done)
            .map((q) => (
              <div className="resp-row" key={q.id}>
                <span className="nm">{q.text}</span>
              </div>
            ))}
        </div>
      )}

      {activeMeds.length > 0 && (
        <div className="card">
          <div className="card-t"><span>Current medication</span></div>
          {activeMeds.map((c) => (
            <div className="course" key={c.id}>
              <div className="nm">
                {c.drug}
                <small>{c.dose || "dose not recorded"} · from {fmtShortYr(c.startDate)}</small>
              </div>
            </div>
          ))}
        </div>
      )}

      {eps.length > 0 && (
        <div className="card">
          <div className="card-t"><span>Episodes</span></div>
          <div className="scrollx">
            <table className="tbl">
              <thead>
                <tr>
                  <th>Onset</th>
                  <th>End</th>
                  <th>Days</th>
                  <th>Gap before</th>
                  <th>Peak sputum</th>
                  <th>Blood</th>
                  <th>Culture</th>
                  <th>Low PF</th>
                  <th>Treatment</th>
                </tr>
              </thead>
              <tbody>
                {eps.map((e, i) => (
                  <tr key={e.id}>
                    <td className="m">{fmtShortYr(e.start)}</td>
                    <td className="m">{fmtShortYr(e.end)}</td>
                    <td className="m">{e.span}</td>
                    <td className="m">{i > 0 ? diffDays(eps[i - 1].end, e.start) : "—"}</td>
                    <td className="m">{e.peakColor != null ? SPUTUM[e.peakColor].label.replace("\n", " ") : "—"}</td>
                    <td className="m" style={{ color: e.blood ? "var(--alarm)" : undefined }}>{e.blood ? "yes" : "—"}</td>
                    <td className="m">{e.minPeakFlow ?? "—"}</td>
                    <td>{e.meds.length ? e.meds.map((m) => m.drug).join(", ") : "—"}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      )}

      {eps.slice(-3).reverse().map((e) => (
        <div className="card" key={"det" + e.id}>
          {/* reference material, not something to scroll past three times over */}
          <details>
            <summary className="card-t foldy">
              <span>Day by day · {fmtShortYr(e.start)}</span>
              <span className="hint">{spanDates(e).length} days</span>
            </summary>
            <div className="scrollx">
              <DayTable dates={spanDates(e)} days={state.days} />
            </div>
          </details>
        </div>
      ))}

      {/* Conditions, reminders and what you track used to sit here. They are
          settings, not something you hand to a clinic, and they were stranded
          under the episode tables — they live behind the gear now. */}

      <div className="sectionhead no-print">Keeping it safe</div>
      <div className="no-print">
        <RescuePack pack={state.rescue || []} onChange={onRescue} />
      </div>

      <div className="card no-print">
        <div className="card-t" id="backup"><span>Backup</span></div>
        <StorageHealth days={Object.keys(state.days).length} />
        <div className="btnrow">
          <button className="btn pri" onClick={shareJson}>Back up now</button>
          <button className="btn" onClick={() => fileRef.current && fileRef.current.click()}>Restore backup</button>
          <button className="btn" onClick={() => checkRef.current && checkRef.current.click()}>Check a backup file</button>
          <button className="btn" onClick={exportJson}>Download instead</button>
          <button className="btn" onClick={onShareWeek}>Copy this week as text</button>
          <button className="btn" onClick={exportCsv}>Download CSV</button>
        </div>
        <input ref={fileRef} type="file" accept="application/json" onChange={importJson} style={{ display: "none" }} />
        <input ref={checkRef} type="file" accept="application/json" onChange={checkFile} style={{ display: "none" }} />
        {check && <div className={"insight " + check.cls}>{check.text}</div>}
        <div className="note" style={{ marginTop: 10 }}>
          <strong>Back up now</strong> saves a file wherever you choose.{" "}
          <strong>Check a backup file</strong> tells you what is in one without changing anything.
        </div>
        <div className="btnrow" style={{ marginTop: 10 }}>
          <Info title="Where to keep your backups" label="Where should these go?">
            <p>
              A backup is one file. The point is to put it somewhere that is not only this phone, so a lost or wiped
              device does not take your log with it.
            </p>
            <h4>Setting it up, once</h4>
            <p>
              <strong>iPhone.</strong> Open the Files app, go to iCloud Drive and make a folder called Clear backups.
              Come back here, tap Back up now, choose Save to Files, and pick that folder.
            </p>
            <p>
              <strong>Android.</strong> Open Drive and make a folder called Clear backups. Then tap Back up now,
              choose Drive, and pick it.
            </p>
            <h4>Every time after that</h4>
            <p>Tap Back up now and your phone offers the same place again. Two taps, once a week is plenty.</p>
            <p>
              The dot at the top of the screen turns amber after a few days and red after a week, so you do not have
              to remember on your own.
            </p>
            <h4>Getting it back</h4>
            <p>
              Restore backup, then pick the newest file. Worth doing once now, while there is nothing to lose, so you
              know it works.
            </p>
            <h4>One thing that is not a backup</h4>
            <p>
              Download CSV gives you a spreadsheet for reading your own numbers. It is not something this app can
              restore from, because it cannot hold your courses, your care plan or its history.
            </p>
          </Info>
        </div>
        <Snapshots onRestore={onImport} />
        <div className="divider" />
        <div className="btnrow">
          <button className="btn danger" onClick={onWipe}>Erase everything</button>
        </div>
      </div>
    </>
  );
}

/* ------------------------------------------------------------------ */
/*  App                                                                */
/* ------------------------------------------------------------------ */

function App() {
  const [state, setState] = useState(emptyState());
  const [ready, setReady] = useState(false);
  const [persist, setPersist] = useState(true);
  const [tab, setTab] = useState("today");
  const [historyMode, setHistoryMode] = useState("episodes");
  const [showMonth, setShowMonth] = useState(false);
  const [showAbout, setShowAbout] = useState(false);
  const [slide, setSlide] = useState("");
  const touch = useRef(null);
  const sheetRef = useRef(null);
  const [stuck, setStuck] = useState(false);
  const [date, setDate] = useState(todayISO());
  // an installed app resumes from background rather than reloading, so the calendar
  // day has to be watched rather than read once at startup
  const [today, setToday] = useState(todayISO());
  const [saved, setSaved] = useState(false);
  const [flash, setFlash] = useState("");
  const timer = useRef(null);
  const first = useRef(true);

  useEffect(() => {
    let live = true;
    loadState().then(({ state: s, ok }) => {
      if (!live) return;
      if (s) setState(s);
      setPersist(ok);
      // ?sample=1 fills an empty log with a made-up year, for screenshots and for
      // anyone who wants a look before committing to it. It refuses to run when
      // there are entries, so a shared link can never overwrite somebody's log.
      try {
        const wants = new URLSearchParams(window.location.search).has("sample");
        if (wants && (!s || !Object.keys(s.days || {}).length)) {
          setState(sampleYear());
          // a made-up year of entries with a red "never backed up" dot over it is
          // not what the sample is showing off, so give it a backup too
          markBackedUp();
          // the save effect skips the first change so that merely loading does not
          // rewrite the file; this is a real change and should be written
          first.current = false;
        }
      } catch (e) {}
      setReady(true);
    });
    return () => { live = false; };
  }, []);

  useEffect(() => {
    if (!ready) return;
    if (first.current) { first.current = false; return; }
    if (timer.current) clearTimeout(timer.current);
    timer.current = setTimeout(async () => {
      const ok = await saveState(state);
      if (ok) {
        setSaved(true);
        setTimeout(() => setSaved(false), 1100);
      }
    }, 700);
    return () => timer.current && clearTimeout(timer.current);
  }, [state, ready]);

  const setDay = useCallback((d, entry) => {
    setState((s) => ({ ...s, days: { ...s.days, [d]: entry } }));
  }, []);

  const addCourse = useCallback((c) => {
    setState((s) => ({ ...s, courses: [...(s.courses || []), c] }));
  }, []);

  const endCourse = useCallback((id, onDate) => {
    setState((s) => ({
      ...s,
      courses: s.courses.map((c) =>
        c.id === id ? { ...c, days: Math.max(1, diffDays(c.startDate, onDate) + 1) } : c
      ),
    }));
  }, []);

  const deleteCourse = useCallback((id) => {
    setState((s) => ({ ...s, courses: s.courses.filter((c) => c.id !== id) }));
  }, []);

  const editCourse = useCallback((id, patch) => {
    setState((s) => ({
      ...s,
      courses: s.courses.map((c) => (c.id === id ? { ...c, ...patch } : c)),
    }));
  }, []);

  // Kept in its own key rather than in day.care, because doseCount and careComplete
  // walk the regimen: a course dose landing in there would quietly rewrite airway-care
  // adherence for every day of the course, and with it the trend charts.
  const setCourseDose = useCallback((d, id, n) => {
    setState((s) => {
      const prev = { ...emptyDay(), ...(s.days[d] || {}) };
      return {
        ...s,
        days: { ...s.days, [d]: { ...prev, courseDoses: { ...(prev.courseDoses || {}), [id]: n } } },
      };
    });
  }, []);

  useEffect(() => {
    const check = () => {
      const now = todayISO();
      setToday((prev) => {
        if (prev === now) return prev;
        // only follow the clock if she was sitting on what used to be today
        setDate((d) => (d === prev ? now : d));
        return now;
      });
    };
    const onVis = () => document.visibilityState === "visible" && check();
    document.addEventListener("visibilitychange", onVis);
    window.addEventListener("focus", check);
    const t = setInterval(check, 60000);
    return () => {
      document.removeEventListener("visibilitychange", onVis);
      window.removeEventListener("focus", check);
      clearInterval(t);
    };
  }, []);

  const episodes = useMemo(() => buildEpisodes(state.days, state.courses), [state.days, state.courses]);

  const run = useMemo(() => wellRun(state.days, episodes), [state.days, episodes, today]);
  const care = useMemo(() => careRun(state.days, state.regimen), [state.days, state.regimen, today]);
  // Clouds clear as you keep up your care, rather than as time passes since an
  // illness. Same picture, but tied to something you can do something about.
  const clarity = care.hasPlan ? 0.25 + 0.75 * care.rate : run.clarity;

  // particulate drift scales with the air she is actually breathing
  const moteOpacity = useMemo(() => {
    const a = state.days[todayISO()] && state.days[todayISO()].aqi;
    const v = a && a.value != null ? a.value : null;
    if (v == null) return 0.05;
    return Math.min(Math.max((v - 35) / 190, 0), 1) * 0.34;
  }, [state.days, today]);

  const dueMilestone = useMemo(() => {
    const seen = (state.meta && state.meta.seenMilestones) || [];
    const hit = MILESTONES.filter((m) => run.current >= m && !seen.includes(m));
    return hit.length ? hit[hit.length - 1] : null;
  }, [run.current, state.meta, today]);

  // shown once, before there is anything to lose
  const [setupOpen, setSetupOpen] = useState(false);
  const [setupDismissed, setSetupDismissed] = useState(false);
  const showIntro = !(state.meta && state.meta.seenIntro) && ready;
  // Straight after the welcome, and only while there is genuinely nothing to lose:
  // no plan and no entries. Derived rather than triggered, so it cannot fire twice.
  const needsPlan =
    ready &&
    !showIntro &&
    !setupDismissed &&
    !(state.regimen || []).length &&
    !Object.keys(state.days || {}).length;
  const ackIntro = useCallback(() => {
    setState((s) => ({ ...s, meta: { ...(s.meta || {}), seenIntro: true } }));
  }, []);

  const ackMilestone = useCallback((m) => {
    setState((s) => ({
      ...s,
      meta: { ...(s.meta || {}), seenMilestones: [...(((s.meta || {}).seenMilestones) || []), m] },
    }));
  }, []);

  // week strip window: the 7-day block that contains the selected date
  const weekEnd = useMemo(() => {
    const back = Math.floor(diffDays(date, todayISO()) / 7);
    return addDays(todayISO(), -Math.max(0, back) * 7);
  }, [date, today]);

  const shareEpisode = async () => {
    const last = episodes.length ? episodes[episodes.length - 1] : null;
    if (!last) return;
    const ok = await copyText(episodeText(last, state.days));
    setFlash(ok ? "Episode copied" : "Copy failed");
    setTimeout(() => setFlash(""), 1800);
  };

  // Full-screen horizontal swipe to change day. The page tracks the finger and, if the
  // swipe commits, carries on off the edge while the next day comes in behind it, so
  // days read as sitting next to each other. Sliders and sideways-scrolling tables
  // keep their own gestures. The transform is written straight to the node rather than
  // held in state: this fires on every touchmove and a re-render of the whole day at
  // that rate drops frames.
  const SWIPE_OUT_MS = 165;

  const goDay = (delta) => {
    if (delta > 0 && date >= today) return;
    setSlide(delta > 0 ? "from-left" : "from-right");
    setDate(addDays(date, delta));
  };

  // The week strip lives in the header, so once you scroll into the entry there is
  // nothing left saying which day you are on — which made swiping sideways feel like
  // it belonged to a different page. This brings the day and its arrows down with you.
  useEffect(() => {
    if (tab !== "today" || !ready) {
      setStuck(false);
      return;
    }
    const el = document.querySelector(".weekrow");
    if (!el || typeof window.IntersectionObserver !== "function") return;
    const io = new window.IntersectionObserver(([e]) => setStuck(!e.isIntersecting), {
      threshold: 0,
    });
    io.observe(el);
    return () => io.disconnect();
  }, [tab, ready]);

  const paint = (dx) => {
    const el = sheetRef.current;
    if (!el) return;
    el.style.transition = "";
    el.style.transform = "translate3d(" + dx + "px,0,0)";
    el.style.opacity = String(Math.max(0.5, 1 - Math.abs(dx) / 560));
  };

  const settle = (dx, ms, gone) => {
    const el = sheetRef.current;
    if (!el) return;
    el.style.transition = "transform " + ms + "ms var(--ease), opacity " + ms + "ms var(--ease)";
    el.style.transform = "translate3d(" + dx + "px,0,0)";
    el.style.opacity = gone ? "0" : "1";
  };

  const onTouchStart = (e) => {
    touch.current = null;
    if (tab !== "today" || showMonth || showAbout) return;
    const t = e.touches && e.touches[0];
    if (!t) return;
    const el = e.target;
    const blocked =
      el && el.closest && el.closest('input[type="range"], .scrollx, textarea, select, .week, .ribbon');
    if (blocked) return;
    touch.current = { x: t.clientX, y: t.clientY, at: Date.now(), axis: null, dx: 0 };
  };

  const onTouchMove = (e) => {
    const st = touch.current;
    if (!st) return;
    const t = e.touches && e.touches[0];
    if (!t) return;
    const dx = t.clientX - st.x;
    const dy = t.clientY - st.y;
    if (st.axis === null) {
      if (Math.abs(dx) < 9 && Math.abs(dy) < 9) return;
      // once the gesture is vertical it belongs to the scroller, and taking it back
      // mid-scroll is worse than never having claimed it
      st.axis = Math.abs(dx) > Math.abs(dy) * 1.2 ? "x" : "y";
      if (st.axis === "y") {
        touch.current = null;
        return;
      }
    }
    // there is no tomorrow to swipe to, so dragging that way resists instead of moving
    st.dx = dx < 0 && date >= today ? dx * 0.24 : dx;
    paint(st.dx);
  };

  const onTouchEnd = () => {
    const st = touch.current;
    touch.current = null;
    if (!st || st.axis !== "x") return;
    const w = (sheetRef.current && sheetRef.current.offsetWidth) || 360;
    const far = Math.abs(st.dx) > Math.min(96, w * 0.24);
    const flick = Date.now() - st.at < 320 && Math.abs(st.dx) > 42;
    const forward = st.dx < 0;
    if ((!far && !flick) || (forward && date >= today)) {
      settle(0, 220, false);
      return;
    }
    settle(forward ? -w : w, SWIPE_OUT_MS, true);
    window.setTimeout(() => {
      setSlide(forward ? "from-left" : "from-right");
      setDate(addDays(date, forward ? 1 : -1));
    }, SWIPE_OUT_MS);
  };

  const wipe = () => {
    if (window.confirm("Erase every entry permanently? Download a backup first if you're not sure.")) {
      setState(emptyState());
    }
  };

  const setStatus = useCallback((d, status) => {
    setState((s) => {
      const prev = { ...emptyDay(), ...(s.days[d] || {}) };
      const next = { ...prev, status };

      // carry the maintenance dose and a sputum starting point forward, so the
      // day opens with sensible values instead of blanks
      const before = Object.keys(s.days).filter((k) => k < d).sort();
      const lastLogged = before.length ? s.days[before[before.length - 1]] : null;
      if (status && next.sputum.color == null && lastLogged && lastLogged.sputum.color != null)
        next.sputum = { ...lastLogged.sputum };
      if (status && !next.blood) next.blood = "none";

      // marking a day unwell sets every symptom to an explicit none, so that
      // "absent" and "never answered" stop being the same value
      if (status === "unwell" && prev.symptomsReviewed === undefined) {
        const zeros = {};
        SYMPTOMS.forEach(([k]) => (zeros[k] = 0));
        (s.customSymptoms || []).forEach((n) => (zeros["c:" + n] = 0));
        next.symptoms = { ...zeros, ...prev.symptoms };
        next.symptomsReviewed = false;
      }
      return { ...s, days: { ...s.days, [d]: next } };
    });
  }, []);

  const setAqi = useCallback((d, aqi) => {
    setState((s) => {
      const prev = { ...emptyDay(), ...(s.days[d] || {}) };
      return { ...s, days: { ...s.days, [d]: { ...prev, aqi } } };
    });
  }, []);

  const clearDay = useCallback((d) => {
    setState((s) => {
      const days = { ...s.days };
      delete days[d];
      return { ...s, days };
    });
  }, []);

  const addTag = useCallback((t) => {
    setState((s) => (s.tags.includes(t) ? s : { ...s, tags: [...s.tags, t] }));
  }, []);

  const deleteTag = useCallback((t) => {
    setState((s) => ({ ...s, tags: s.tags.filter((x) => x !== t) }));
  }, []);

  const addLocation = useCallback((l) => {
    setState((s) =>
      (s.locations || []).some((x) => x.name === l.name)
        ? s
        : { ...s, locations: [l, ...(s.locations || [])].slice(0, 12) }
    );
  }, []);

  const shareText = useCallback(async (title, text, filename) => {
    try {
      if (navigator.share) {
        await navigator.share({ title, text });
        return true;
      }
    } catch (e) {
      if (e && e.name === "AbortError") return true;
    }
    const ok = await copyText(text);
    setFlash(ok ? "Copied, paste it into Notes" : "Could not share");
    setTimeout(() => setFlash(""), 2400);
    return ok;
  }, []);

  const shareBackup = useCallback(async () => {
    const body = JSON.stringify(state, null, 2);
    const name = `clear-backup-${todayISO()}.json`;
    try {
      const file = new File([body], name, { type: "application/json" });
      if (navigator.canShare && navigator.canShare({ files: [file] })) {
        await navigator.share({ files: [file], title: "Clear backup" });
        markBackedUp();
        setFlash("Backed up");
        setTimeout(() => setFlash(""), 1800);
        return;
      }
    } catch (e) {
      if (e && e.name === "AbortError") return;
    }
    try {
      const url = URL.createObjectURL(new Blob([body], { type: "application/json" }));
      const a = document.createElement("a");
      a.href = url;
      a.download = name;
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      markBackedUp();
      setFlash("Backup saved");
      setTimeout(() => setFlash(""), 1800);
    } catch (e) {}
  }, [state]);

  // Hands the reminder times to the phone's own calendar as a .ics. A real
  // calendar entry keeps nudging whether or not this app is open, which a web
  // notification cannot promise on iOS.
  const addRemindersToCalendar = useCallback(async () => {
    const times = state.remindTimes || [];
    if (!times.length) return;
    const ics = reminderIcs(times, "Airway care");
    const name = "clear-reminders.ics";
    try {
      const file = new File([ics], name, { type: "text/calendar" });
      if (navigator.canShare && navigator.canShare({ files: [file] })) {
        await navigator.share({ files: [file], title: "Clear reminders" });
        setFlash("Added");
        setTimeout(() => setFlash(""), 1800);
        return;
      }
    } catch (e) {
      if (e && e.name === "AbortError") return;
    }
    download(name, ics, "text/calendar");
  }, [state.remindTimes]);

  // remembers the exact set of signals that was on screen when it was closed, so
  // anything new or anything worse gets past it
  const dismissWarning = useCallback((sig) => setState((s) => ({ ...s, ewSeen: sig })), []);

  const setFoldOpen = useCallback(
    (id, open) => setState((s) => ({ ...s, folds: { ...(s.folds || {}), [id]: open } })),
    []
  );

  // what has been acknowledged, and in what state — see Callout
  const setNoted = useCallback(
    (id, sig) => setState((s) => ({ ...s, noted: { ...(s.noted || {}), [id]: sig } })),
    []
  );

  const setRescue = useCallback((r) => setState((s) => ({ ...s, rescue: r })), []);
  const setAppt = useCallback((a) => setState((s) => ({ ...s, appt: a })), []);
  const setQuestions = useCallback((q) => setState((s) => ({ ...s, questions: q })), []);

  const setRegimen = useCallback((r) => {
    setState((s) => ({ ...s, regimen: r }));
  }, []);

  const setTrack = useCallback((t) => {
    setState((s) => ({ ...s, track: t }));
  }, []);

  const setRemind = useCallback((t) => {
    setState((s) => ({ ...s, remindTimes: t }));
  }, []);

  const setConditions = useCallback((c) => {
    setState((s) => ({ ...s, conditions: c }));
  }, []);

  const setUnit = useCallback((u) => {
    setState((s) => ({ ...s, weightUnit: u }));
  }, []);

  const addPrnMed = useCallback((n) => {
    setState((s) =>
      (s.prnMeds || []).includes(n) ? s : { ...s, prnMeds: [...(s.prnMeds || []), n] }
    );
  }, []);

  const addCustomDrug = useCallback((n) => {
    setState((s) =>
      (s.customDrugs || []).some((d) => d.name === n.name)
        ? s
        : { ...s, customDrugs: [...(s.customDrugs || []), n] }
    );
  }, []);

  // A name typed once is remembered for the dropdown, so a typo would otherwise
  // follow you around for good. These only forget the suggestion; courses and days
  // already recorded against the name keep it.
  const deletePrnMed = useCallback((n) => {
    setState((s) => ({ ...s, prnMeds: (s.prnMeds || []).filter((x) => x !== n) }));
  }, []);

  const deleteCustomDrug = useCallback((name) => {
    setState((s) => ({ ...s, customDrugs: (s.customDrugs || []).filter((d) => d.name !== name) }));
  }, []);

  const setCourseNote = useCallback((id, outcomeNote) => {
    setState((s) => ({
      ...s,
      courses: s.courses.map((c) => (c.id === id ? { ...c, outcomeNote } : c)),
    }));
  }, []);

  const setCourseOutcome = useCallback((id, outcome) => {
    setState((s) => ({
      ...s,
      courses: s.courses.map((c) => (c.id === id ? { ...c, outcome } : c)),
    }));
  }, []);

  const addCustomSymptom = useCallback((n) => {
    setState((s) =>
      (s.customSymptoms || []).includes(n) ? s : { ...s, customSymptoms: [...(s.customSymptoms || []), n] }
    );
  }, []);

  const deleteCustomSymptom = useCallback((n) => {
    setState((s) => ({ ...s, customSymptoms: (s.customSymptoms || []).filter((x) => x !== n) }));
  }, []);

  const quickWell = useCallback((d) => {
    setState((s) => {
      const prev = { ...emptyDay(), ...(s.days[d] || {}) };
      const wellKeys = Object.keys(s.days)
        .filter((k) => k < d && s.days[k].status === "well")
        .sort();
      const lw = wellKeys.length ? s.days[wellKeys[wellKeys.length - 1]] : null;
      return {
        ...s,
        days: {
          ...s.days,
          [d]: {
            ...prev,
            status: "well",
            sputum:
              prev.sputum.color != null
                ? prev.sputum
                : lw
                ? { ...lw.sputum }
                : { color: 0, volume: 2, texture: 3 },
            blood: prev.blood || "none",
            symptoms: {},
          },
        },
      };
    });
  }, []);

  if (!ready) {
    return (
      <div className="bx">
        <style>{CSS}</style>
        <div className="sky" style={{ paddingBottom: 90 }}>
          <div className="sky-in">
            <div className="sky-title">
              <h1>Clear</h1>
            </div>
          </div>
        </div>
      </div>
    );
  }

  // read on every render rather than held in state: markBackedUp writes straight to
  // localStorage, and the render that follows it should already show the new colour
  const backup = backupStatus();

  const TITLES = {
    today: ["Clear", "bronchiectasis"],
    history: ["History", "everything on record"],
    report: ["Report", "for your respiratory team"],
  };

  return (
    <div className="bx">
      <style>{CSS}</style>

      <div
        className={"sky no-print" + (tab === "today" ? "" : " compact")}
        style={{ "--clarity": clarity }}
      >
        {tab === "today" && (
          <>
            <div className="clouds" style={{ opacity: 0.2 + 0.62 * (1 - clarity) }}>
              <CloudLayer cls="cl-far" id="cf" seed="7" freq="0.004 0.011" cut="-0.62" gain="1.5" />
              <CloudLayer cls="cl-mid" id="cm" seed="19" freq="0.006 0.017" cut="-0.7" gain="1.7" />
              <CloudLayer cls="cl-near" id="cn" seed="31" freq="0.009 0.024" cut="-0.78" gain="1.9" />
            </div>
            <div className="motes" style={{ opacity: moteOpacity }} />
          </>
        )}
        <div className="haze" style={{ opacity: 0.42 * (1 - clarity) }} />
        <div className="sky-in">
          <div className="sky-title">
            <h1>{TITLES[tab][0]}</h1>
            <div className="skyacts">
              {tab === "today" ? (
                <>
                  {date !== today && (
                    <button
                      className="monthbtn"
                      onClick={() => {
                        setSlide(date < today ? "from-left" : "from-right");
                        setDate(today);
                      }}
                    >
                      Today
                    </button>
                  )}
                  <button
                    className={"monthbtn" + (showMonth ? " open" : "")}
                    aria-expanded={showMonth}
                    onClick={() => setShowMonth((v) => !v)}
                  >
                    Month<span className="cv">{"▾"}</span>
                  </button>
                </>
              ) : (
                <span className="sub">{TITLES[tab][1]}</span>
              )}
              <button
                className={"bpill " + backup.tone}
                aria-label={backup.label + ". Open backup."}
                title={backup.label}
                onClick={() => {
                  setTab("report");
                  setTimeout(() => {
                    const el = document.getElementById("backup");
                    if (el) el.scrollIntoView({ block: "start", behavior: "smooth" });
                  }, 80);
                }}
              >
                <span className="bd" />
                <span className="bt">{backup.short}</span>
              </button>
              <button
                className="iconbtn"
                aria-label="Settings"
                onClick={() => setShowAbout((v) => !v)}
              >
                <Gear />
              </button>
            </div>
          </div>

          {tab === "history" && (
            <div className="pillbar">
              <button
                className={historyMode === "episodes" ? "on" : ""}
                onClick={() => setHistoryMode("episodes")}
              >
                Episodes
              </button>
              <button
                className={historyMode === "patterns" ? "on" : ""}
                onClick={() => setHistoryMode("patterns")}
              >
                Patterns
              </button>
            </div>
          )}

          {tab === "today" && (
            <>
              <WeekStrip date={date} setDate={setDate} days={state.days} weekEnd={weekEnd} />
              <StatusFork
                day={state.days[date]}
                onWell={() => quickWell(date)}
                onIll={() => setStatus(date, "unwell")}
                onClear={() => setStatus(date, null)}
              />
              <Hero episodes={episodes} days={state.days} date={date} run={run} care={care} regimen={state.regimen} compact />
              <GlassStats days={state.days} date={date} regimen={state.regimen} />
            </>
          )}
        </div>
      </div>

      {tab === "today" && stuck && !showMonth && !showAbout && (
        <div className="daybar no-print">
          <button className="wnav" aria-label="Previous day" onClick={() => goDay(-1)}>
            {"‹"}
          </button>
          <button className="dayname" onClick={() => setShowMonth(true)}>
            <b>
              {parseISO(date).toLocaleDateString(undefined, {
                weekday: "short",
                day: "numeric",
                month: "short",
              })}
            </b>
            <span className="cv">{"▾"}</span>
          </button>
          {date !== today && (
            <button className="todaychip" onClick={() => goDay(diffDays(date, today))}>
              Today
            </button>
          )}
          <button
            className="wnav"
            aria-label="Next day"
            disabled={date >= today}
            onClick={() => goDay(1)}
          >
            {"›"}
          </button>
        </div>
      )}

      {tab === "today" && showMonth && (
        <>
          <div className="scrim no-print" onClick={() => setShowMonth(false)} />
          <div className="calwrap no-print">
            <div className="calgrab" />
            <MonthPanel
              days={state.days}
              date={date}
              setDate={(d) => {
                setDate(d);
                setShowMonth(false);
              }}
              onClose={() => setShowMonth(false)}
              regimen={state.regimen}
            />
          </div>
        </>
      )}

      <div
        className={"sheet " + slide + (tab === "today" ? " swipeable" : "")}
        key={tab + date + slide}
        ref={sheetRef}
        onTouchStart={onTouchStart}
        onTouchMove={onTouchMove}
        onTouchEnd={onTouchEnd}
        onTouchCancel={onTouchEnd}
      >
        {tab === "today" && dueMilestone && (
          <Milestone value={dueMilestone} run={run} onDismiss={() => ackMilestone(dueMilestone)} />
        )}

        {!persist && (
          <div className="banner red">
            <strong>Nothing you enter is being saved.</strong> Artifact storage only works once an artifact has been
            published, and it fails silently until then. Publish this artifact from the panel menu, or wait for the
            standalone build. Until one of those, treat this as a preview and export a backup before you close it.
          </div>
        )}

        {date !== todayISO() && tab === "today" && (
          <div className="nudge act no-print">
            <span>Editing {fmtLong(date)}.</span>
            <button
              className="btn sm pri"
              onClick={() => {
                setSlide("from-left");
                setDate(todayISO());
              }}
            >
              Back to today
            </button>
          </div>
        )}

        {tab !== "report" && tab !== "today" && (
          <div className="no-print">
            <Ribbon
              days={state.days}
              span={90}
              onPick={(d) => {
                setDate(d);
                setTab("today");
              }}
            />
          </div>
        )}

        {tab === "today" && (
          <TodayView
            state={state}
            episodes={episodes}
            setDay={setDay}
            date={date}
            setDate={setDate}
            addCourse={addCourse}
            endCourse={endCourse}
            deleteCourse={deleteCourse}
            editCourse={editCourse}
            setCourseDose={setCourseDose}
            deleteCustomSymptom={deleteCustomSymptom}
            deletePrnMed={deletePrnMed}
            deleteCustomDrug={deleteCustomDrug}
            onSetup={() => setSetupOpen(true)}
            addTag={addTag}
            addCustomSymptom={addCustomSymptom}
            setStatus={setStatus}
            clearDay={clearDay}
            onShareEpisode={shareEpisode}
            deleteTag={deleteTag}
            addPrnMed={addPrnMed}
            addLocation={addLocation}
            setAqi={setAqi}
            setRegimen={setRegimen}
            setTab={setTab}
            setRescue={setRescue}
            setQuestions={setQuestions}
            onDismissWarning={dismissWarning}
            onFold={setFoldOpen}
            onNote={setNoted}
            addCustomDrug={addCustomDrug}
            setCourseOutcome={setCourseOutcome}
            setCourseNote={setCourseNote}
          />
        )}
        {tab === "history" &&
          (historyMode === "patterns" ? (
            <TrendsView state={state} episodes={episodes} />
          ) : (
            <EpisodesView state={state} episodes={episodes} setDate={setDate} setTab={setTab} />
          ))}
        {tab === "report" && (
          <ReportView
            state={state}
            episodes={episodes}
            onImport={(s) => setState(s)}
            onWipe={wipe}
            onAppt={setAppt}
            onQuestions={setQuestions}
            onRescue={setRescue}
            onShareWeek={() => shareText("Clear, this week", weekDigest(state.days, state.regimen))}
          />
        )}
      </div>

      {(setupOpen || needsPlan) && (
        <Setup
          regimen={state.regimen || []}
          track={state.track || {}}
          conditions={state.conditions || []}
          unit={state.weightUnit}
          onConditions={setConditions}
          onUnit={setUnit}
          onChange={(r) => {
            setRegimen(r);
            // saving the plan makes needsPlan false, which would unmount the sheet
            // between step one and step two; pin it open so it can finish
            setSetupOpen(true);
          }}
          onTrack={setTrack}
          onClose={() => {
            setSetupOpen(false);
            setSetupDismissed(true);
          }}
        />
      )}

      {(showAbout || showIntro) && (
        <About
          intro={showIntro}
          onClose={() => setShowAbout(false)}
          onAck={ackIntro}
          onShareBackup={shareBackup}
          onShareWeek={() => shareText("Clear, this week", weekDigest(state.days, state.regimen))}
          settings={{
            conditions: state.conditions,
            onConditions: setConditions,
            remindTimes: state.remindTimes,
            onRemind: setRemind,
            onAddRemind: addRemindersToCalendar,
            track: state.track,
            onTrack: setTrack,
            unit: state.weightUnit,
            onUnit: setUnit,
          }}
        />
      )}

      {(flash || saved) && <div className="saved no-print">{flash || "Saved"}</div>}

      <nav className="nav no-print">
        <div className="nav-in">
          {[
            ["today", "Log"],
            ["history", "History"],
            ["report", "Report"],
          ].map(([k, l]) => (
            <button key={k} className={tab === k ? "on" : ""} onClick={() => setTab(k)}>
              {l}
            </button>
          ))}
        </div>
      </nav>
    </div>
  );
}

/* ------------------------------------------------------------------ */
/*  Mount                                                              */
/* ------------------------------------------------------------------ */

// If a render ever throws, the export button goes down with the app and the data
// becomes unreachable through the interface. This screen is deliberately dumb: inline
// styles, no app CSS, no state, and it reads storage directly.
function Rescue({ err }) {
  const [msg, setMsg] = useState("");
  const raw = (() => {
    try {
      return localStorage.getItem(STORE_KEY) || "";
    } catch (e) {
      return "";
    }
  })();

  const save = () => {
    try {
      const url = URL.createObjectURL(new Blob([raw], { type: "application/json" }));
      const a = document.createElement("a");
      a.href = url;
      a.download = "clear-rescue-" + new Date().toISOString().slice(0, 10) + ".json";
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      setMsg("Saved. Keep that file.");
    } catch (e) {
      setMsg("Could not save. Copy the text below instead.");
    }
  };

  const box = {
    font: "16px/1.6 -apple-system, system-ui, sans-serif",
    color: "#0B2A34",
    background: "#EFF2F6",
    minHeight: "100vh",
    padding: "40px 22px 60px",
    boxSizing: "border-box",
  };
  const btn = {
    display: "block",
    width: "100%",
    padding: "15px 18px",
    marginTop: 10,
    borderRadius: 14,
    border: "none",
    background: "#057BC1",
    color: "#fff",
    fontSize: 16,
    fontWeight: 600,
  };
  const alt = { ...btn, background: "#fff", color: "#0B2A34", boxShadow: "inset 0 0 0 1px rgba(8,54,69,.14)" };

  return (
    <div style={box}>
      <h1 style={{ fontSize: 24, fontWeight: 700, margin: "0 0 12px", letterSpacing: "-0.02em" }}>
        Clear could not start
      </h1>
      <p style={{ margin: "0 0 6px" }}>
        Your entries are still on this device. Save them to a file first, before anything else.
      </p>
      <p style={{ margin: "0 0 20px", color: "#5B7280", fontSize: 14 }}>
        {raw ? Math.max(1, Math.round(raw.length / 1024)) + " KB of data found." : "No stored data was found."}
      </p>

      {raw ? <button style={btn} onClick={save}>Save my data to a file</button> : null}
      <button style={alt} onClick={() => window.location.reload()}>Try again</button>

      {msg ? <p style={{ marginTop: 14, fontWeight: 600 }}>{msg}</p> : null}

      <p style={{ marginTop: 28, fontSize: 13, color: "#5B7280" }}>
        Once your data is saved, reopening the app usually clears this. If it keeps happening, send the message
        below to whoever maintains this and restore from your file afterwards.
      </p>
      <pre
        style={{
          marginTop: 10,
          padding: 14,
          background: "#fff",
          borderRadius: 12,
          fontSize: 12,
          whiteSpace: "pre-wrap",
          wordBreak: "break-word",
          color: "#8A3B3B",
        }}
      >
        {String((err && err.message) || err || "unknown error")}
      </pre>
      {raw ? (
        <>
          <p style={{ marginTop: 22, fontSize: 13, color: "#5B7280" }}>
            If the button above did nothing, select all of this and paste it somewhere safe.
          </p>
          <textarea
            readOnly
            value={raw}
            style={{ width: "100%", height: 180, marginTop: 8, borderRadius: 12, border: "none", padding: 12, fontSize: 11 }}
          />
        </>
      ) : null}
    </div>
  );
}

class Boundary extends React.Component {
  constructor(p) {
    super(p);
    this.state = { err: null };
  }
  static getDerivedStateFromError(err) {
    return { err };
  }
  componentDidCatch(err) {
    try {
      console.error(err);
    } catch (e) {}
  }
  render() {
    if (this.state.err) return React.createElement(Rescue, { err: this.state.err });
    return this.props.children;
  }
}

const el = document.getElementById("root");
if (el) createRoot(el).render(React.createElement(Boundary, null, React.createElement(App)));
